COLLDATA("tadabburar","ar",[[59,"§آل عمران\nwords\nتَلبِسُونَتَخلِطُونَ.\nوَجهَ النَّهَارِأَوَّلَهُ.\nبِقِنطَارٍالمَالِ الكَثِيرِ.\nالأُمِّيِّينَالعَرَبِ؛ لأِنَّهُم أُمَّةٌ أُمِّيَّةٌ.\nخَلاَقَنَصِيبَ.\ndeeds\nسل الله تعالى من فضله ورحمته؛ ففضل الله سبحانه أوسع مما يتخيله عقلك.\nناقش مخالفًا لك، واذكر ما في رأيه من صواب وحق حتى تدرب نفسك على الإنصاف وقول الحق.\nتذكر أمانة عندك، وبادر بأدائها إلى أهلها.\nguid\nإحقاق الحق وبيان ما عند الخصم من صواب منهج إسلامي في إنصاف الخصوم.\nالكبر واحتقار الآخرين سبب من أسباب أكل أموال الناس بالباطل.\nلا تجعل يمينك وحلفك بالله سببًا لبيعك وربحك.\nrefl\nيَٰٓأَهۡلَ ٱلۡكِتَٰبِ لِمَ تَلۡبِسُونَ ٱلۡحَقَّ بِٱلۡبَٰطِلِ وَتَكۡتُمُونَ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ ٧١\nالعلماء إذا لبسوا الحق بالباطل فلم يميزوا بينهما، بل أبقوا الأمر مبهمًا، وكتموا الحق الذي يجب عليهم إظهاره؛ ترتب على ذلك من خفاء الحق وظهور الباطل ما ترتب، ولم يهتد العوام الذين يريدون الحق لمعرفته حتى يؤثروه، والمقصود من أهل العلم أن يظهروا للناس الحق، ويعلنوا به، ويميزوا الحق من الباطل. السعدي: ١٣٤-١٣٥.\nما خطورة تلبيس العالم على الناس، وكتم الحق في أمور الدين؟\nوَلَا تُؤۡمِنُوٓاْ إِلَّا لِمَن تَبِعَ دِينَكُمۡ قُلۡ إِنَّ ٱلۡهُدَىٰ هُدَى ٱللَّهِ أَن يُؤۡتَىٰٓ أَحَدٞ مِّثۡلَ مَآ أُوتِيتُمۡ أَوۡ يُحَآجُّوكُمۡ عِندَ رَبِّكُمۡۗ قُلۡ إِنَّ ٱلۡفَضۡلَ بِيَدِ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ ٧٣\nالتقدير: وَلا تُؤمِنُوا بأن يؤتى أحد مثل ما أوتيتم، وهم المسلمون: أوتوا كتابًا سماويًّا كالتوراة، ونبيًّا مرسلًا كموسى، وبأن يحاجوكم ويغلبوكم بالحجة يوم القيامة؛ إلا لأتباعكم. وحاصله أنهم نهَوهم عن إظهار هذين الأمرين المسلّمين لئلَّا يزدادوا تصلبًا، ولمشركي العرب لئلَّا يبعثهم على الإسلام. الألوسي: ٣/٢٠٠.\nالغيرة والحسد قد تمنع من قبول الحق، وضح ذلك من الآية.\nوَمِنۡ أَهۡلِ ٱلۡكِتَٰبِ مَنۡ إِن تَأۡمَنۡهُ بِقِنطَارٖ يُؤَدِّهِۦٓ إِلَيۡكَ وَمِنۡهُم مَّنۡ إِن تَأۡمَنۡهُ بِدِينَارٖ لَّا يُؤَدِّهِۦٓ إِلَيۡكَ إِلَّا مَا دُمۡتَ عَلَيۡهِ قَآئِمٗاۗ\nالآية إخبار أن أهل الكتاب على قسمين: أمين، وخائن. وذكر القنطار مثالًا للكثير، فمن أداه أدى ما دونه. ابن جزي: ١/١٥٠.\nبيّن كيف أنصف القرآن الكريم مخالفيه من أهل الديانات الأخرى.\nوَمِنۡ أَهۡلِ ٱلۡكِتَٰبِ مَنۡ إِن تَأۡمَنۡهُ بِقِنطَارٖ يُؤَدِّهِۦٓ إِلَيۡكَ وَمِنۡهُم مَّنۡ إِن تَأۡمَنۡهُ بِدِينَارٖ لَّا يُؤَدِّهِۦٓ إِلَيۡكَ إِلَّا مَا دُمۡتَ عَلَيۡهِ قَآئِمٗاۗ\nالأمانة عظيمة القدر في الدين، ومن عِظَم قدرها أنها تقوم هي والرحم على جنبتي الصراط -كما في صحيح مسلم-؛ فلا يُمَكَّن من الجواز إلا من حفظهما. القرطبي: ٥/١٧٨-١٧٩.\nبيّن عظم الأمانة، وخطر الخيانة باختصار.\nذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَيۡسَ عَلَيۡنَا فِي ٱلۡأُمِّيِّۧنَ سَبِيلٞ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ\n(ليس) عليهم (في الأميين سبيل) أي: ليس عليهم إثم في عدم أداء أموالهم إليهم؛ لأنهم -بزعمهم الفاسد ورأيهم الكاسد- قد احتقروهم غاية الاحتقار، ورأوا أنفسهم في غاية العظمة -وهم الأذلاء الأحقرون-؛ فلم يجعلوا للأميين حرمة، وأجازوا ذلك؛ فجمعوا بين أكل الحرام، واعتقاد حله، وكان هذا كذبًا على الله. السعدي: ١٣٥.\nاحتواء اليهود لأكثر أموال العالم مبني على قاعدة فاسدة، بينها من الآية.\nذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَيۡسَ عَلَيۡنَا فِي ٱلۡأُمِّيِّۧنَ سَبِيلٞ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ ٧٥\nوذلك أن اليهود قالوا: أموال العرب حلال لنا؛ لأنهم ليسوا على ديننا، ولا حرمة لهم في كتابنا، وكانوا يستحلون ظلم من خالفهم في دينهم. البغوي: ١/٣٧١.\nإلى أي حد بلغ ظلم اليهود وعنصريتهم؟\nبَلَىٰۚ مَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ ٧٦\nالوفاء بالعهود من التقوى التي يحبها الله، والوفاء بالعهود هو جملة المأمور به؛ فإن الواجب إما بالشرع أو بالشرط، وكل ذلك فعل مأمور به، وذلك وفاء بعهد الله وعهد العبيد. ابن تيمية: ٢/٨٥.\nما فضيلة الوفاء بالعهود المذكورة في الآية؟"],[60,"§آل عمران\nwords\nيَلوُونَيُحَرِّفُونَ الكَلاَمَ عَن مَوَاضِعِهِ.\nرَبَّانِيِّينحُكَمَاءَ، فُقَهَاءَ، مُعَلِّمِينَ.\nإِصرِيعَهدِي.\ndeeds\nعلِّم أحدًا ممن حولك صفة الوضوء، ثم الصلاة؛ فذلك من تربية الناس على صغار العلم قبل كباره.\nحدد مسألة تعلمتها، واعمل بها حتى تسير على خطى الربانيين.\nساهم بمشروع تنصر به دين الله تعالى.\nguid\nجرأة اليهود على الكذب على الله، وعلى الناس.\nعلى الداعية وطالب العلم أن يتذكر دائمًا أنه إنَّما يدعو لله، لا لنفسه.\nعلى العالم والداعية أن يبدأ بتعليم صغار العلم قبل كباره، والعمل بما يعلم.\nrefl\nوَإِنَّ مِنۡهُمۡ لَفَرِيقٗا يَلۡوُۥنَ أَلۡسِنَتَهُم بِٱلۡكِتَٰبِ لِتَحۡسَبُوهُ مِنَ ٱلۡكِتَٰبِ وَمَا هُوَ مِنَ ٱلۡكِتَٰبِ وَيَقُولُونَ هُوَ مِنۡ عِندِ ٱللَّهِ وَمَا هُوَ مِنۡ عِندِ ٱللَّهِ\nوذلك أن المقصود من الكتاب: حفظ ألفاظه، وعدم تغييرها، وفهم المراد منها وإفهامه. وهؤلاء عكسوا القضية، وأفهموا غير المراد من الكتاب؛ إما تعريضًا، وإما تصريحًا. السعدي: ١٣٦.\nبينت الآية نوعًا من التحريف والتلاعب بكتاب الله، وضح ذلك.\nوَإِنَّ مِنۡهُمۡ لَفَرِيقٗا يَلۡوُۥنَ أَلۡسِنَتَهُم بِٱلۡكِتَٰبِ لِتَحۡسَبُوهُ مِنَ ٱلۡكِتَٰبِ وَمَا هُوَ مِنَ ٱلۡكِتَٰبِ وَيَقُولُونَ هُوَ مِنۡ عِندِ ٱللَّهِ وَمَا هُوَ مِنۡ عِندِ ٱللَّهِ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ ٧٨\nوجيء بالمضارع في هاته الأفعال: يلوون، ويقولون؛ للدلالة على تجدد ذلك، وأنه دأبهم. ابن عاشور: ٣/٢٩٢.\nلماذا جاءت الأفعال بصيغة المضارع في الآية الكريمة؟\nوَإِنَّ مِنۡهُمۡ لَفَرِيقٗا يَلۡوُۥنَ أَلۡسِنَتَهُم بِٱلۡكِتَٰبِ لِتَحۡسَبُوهُ مِنَ ٱلۡكِتَٰبِ وَمَا هُوَ مِنَ ٱلۡكِتَٰبِ\nوالتحريف قد فسر بتحريف التنزيل، وبتحريف التأويل؛ فأما تحريف التأويل فكثير جدًّا، وقد ابتليت به طوائف من هذه الأمة. وأمَّا تحريف التنزيل فقد وقع في كثير من الناس؛ يحرفون ألفاظ الرسول، ويروون الحديث بروايات منكرة. ابن تيمية: ٢/٨٦.\nتحريف الوحي على قسمين، فما هما؟\nوَلَٰكِن كُونُواْ رَبَّٰنِيِّۧنَ بِمَا كُنتُمۡ تُعَلِّمُونَ ٱلۡكِتَٰبَ وَبِمَا كُنتُمۡ تَدۡرُسُونَ ٧٩\nأي: تابعين طريق الرب، منسوبين إليه بكمال العلم المزين بالعمل؛ فإن الرباني هو الشديد التمسك بدين الله -سبحانه وتعالى- وطاعته. البقاعي: ٢/١١٨.\nما صفات الربانيين؟\nوَلَٰكِن كُونُواْ رَبَّٰنِيِّۧنَ بِمَا كُنتُمۡ تُعَلِّمُونَ ٱلۡكِتَٰبَ وَبِمَا كُنتُمۡ تَدۡرُسُونَ ٧٩\n(ربانيين): قال سعيد بن جبير: \"العالم الذي يعمل بعلمه\"... وقيل: الربانيون فوق الأحبار؛ والأحبار: العلماء، والربانيون: الذين جمعوا مع العلم البصارة بسياسة الناس.. البغوي: ١/٣٧٥.\nكيف تكون عالمًا ربانيًا؟\nوَلَٰكِن كُونُواْ رَبَّٰنِيِّۧنَ بِمَا كُنتُمۡ تُعَلِّمُونَ ٱلۡكِتَٰبَ وَبِمَا كُنتُمۡ تَدۡرُسُونَ ٧٩\nفإن فائدة الدرس العلم، وفائدة العلم العمل؛ ومنه: الحث على الخير، والمراقبة للخالق. البقاعي: ٢/١١٨.\nما فائدة الدروس وطلب العلم؟\nوَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّۧنَ لَمَآ ءَاتَيۡتُكُم مِّن كِتَٰبٖ وَحِكۡمَةٖ ثُمَّ جَآءَكُمۡ رَسُولٞ مُّصَدِّقٞ لِّمَا مَعَكُمۡ لَتُؤۡمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥۚ قَالَ ءَأَقۡرَرۡتُمۡ وَأَخَذۡتُمۡ عَلَىٰ ذَٰلِكُمۡ إِصۡرِيۖ قَالُوٓاْ أَقۡرَرۡنَاۚ قَالَ فَٱشۡهَدُواْ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ ٨١\nوروي عن غير واحد من السلف -علي وابن عباس وغيرهما- قالوا: \"لم يبعث الله نبيًّا من عهد نوح إلا أخذ عليه الميثاق: لئن بُعث محمد وهو حي ليؤمنن به ولينصرنه، وأمره أن يأخذ الميثاق على أمته: لئن بُعث محمد -وهم أحياء- ليؤمنن به ولينصرنه\". ابن تيمية: ٢/٨٨.\nبيّن منزلة النبي محمد -صلى الله عليه وسلم-."],[61,"§آل عمران\nwords\nوَالأَسبَاطِالأَنبِيَاءِ الَّذِينَ كَانُوا فِي قَبَائِلِ بَنِي إِسرَائِيلَ الاِثنَتَي عَشرَةَ.\ndeeds\nادع أحد الكفار إلى الإسلام مستخدمًا وسائل التواصل الحديثة، أو غيرها من الأساليب.\nأرسل رسالة ترد فيها على أهل وحدة الأديان وحرية التدين من خلال الآية.\nتذكر ذنبًا فعلته، وأكثر من الاستغفار منه، ثم تصدق بصدقة عسى الله أن يغفره لك.\nguid\nقاعدة صريحة لا تقبل التأويل، ولا التحريف: الإسلام هو الدين الوحيد الذي يقبله الله من العبد.\nباب التوبة لا يقفل أمام عاصٍ؛ مهما بالغ في الكفر أو المعاصي.\nما أجمل التوبة إذا تبعها إصلاح ودعوة.\nrefl\nوَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينٗا فَلَن يُقۡبَلَ مِنۡهُ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ ٨٥\nالآية إبطال لجميع الأديان غير الإسلام. ابن جزي: ١/١٥١.\nبم ترد على من يقول: بما أنَّ اليهودية والنصرانية أديان سماوية، فلا نكفِّر من يتعبد بهما؟\nوَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينٗا فَلَن يُقۡبَلَ مِنۡهُ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ ٨٥\nبيَّن أن الدين الذي رضيه ويقبله من عباده هو الإسلام، ولا يكون الدين في محل الرضى والقبول إلا بانضمام التصديق إلى العمل. ابن تيمية: ٢/٩٦.\nمتى يكون الدين مقبولًا؟\nكَيۡفَ يَهۡدِي ٱللَّهُ قَوۡمٗا كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ وَشَهِدُوٓاْ أَنَّ ٱلرَّسُولَ حَقّٞ وَجَآءَهُمُ ٱلۡبَيِّنَٰتُۚ\nفهؤلاء لا يوفقون للهداية؛ لأن الذي يُرجى أن يهتدي هو الذي لم يعرف الحق، وهو حريص على التماسه؛ فهذا بالحري أن ييسر الله له أسباب الهداية، ويصونه من أسباب الغواية. السعدي: ١٣٧.\nمَن الكافرون الذين يتوقع منهم الهداية والإيمان؟\nكَيۡفَ يَهۡدِي ٱللَّهُ قَوۡمٗا كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ وَشَهِدُوٓاْ أَنَّ ٱلرَّسُولَ حَقّٞ وَجَآءَهُمُ ٱلۡبَيِّنَٰتُۚ\nأي: قامت عليهم الحجج والبراهين على صدق ما جاءهم به الرسول، ووضح لهم الأمر، ثم ارتّدوا إلى ظلمة الشرك؛ فكيف يستحق هؤلاء الهداية بعد ما تلبسوا به من العماية؟ ابن كثير: ١/٣٥٩.\nلماذا كان الموصوفون في الآية لا يستحقون الهداية؟\nإِنَّ ٱلَّذِينَ كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّن تُقۡبَلَ تَوۡبَتُهُمۡ\nأي: لا يوفقون لتوبة تقبل، بل يمدهم الله في طغيانهم يعمهون... فهذا هو الذي سعى في قطع أسباب رحمة ربه عنه، وهو الذي سد على نفسه باب التوبة. السعدي: ١٣٧\nلماذا لم تُقبل توبة المذكورين في الآية؟\nإِنَّ ٱلَّذِينَ كَفَرُواْ بَعۡدَ إِيمَٰنِهِمۡ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّن تُقۡبَلَ تَوۡبَتُهُمۡ وَأُوْلَٰٓئِكَ هُمُ ٱلضَّآلُّونَ ٩٠\nلأن الله -سبحانه وتعالى- يطبع على قلوبهم؛ فلا يتوبون توبة نصوحًا يدومون عليها، ويصلحون ما فسد، أو لن توجد منهم توبة حتى يترتب عليها القبول؛ لأنهم زادوا عن أهل القسم الأول بالتمادي. البقاعي: ٢/١٢٣.\nلماذا لن تقبل توبة من يتكرر منه الكفر بعد الإيمان؟\nإِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٞ فَلَن يُقۡبَلَ مِنۡ أَحَدِهِم مِّلۡءُ ٱلۡأَرۡضِ ذَهَبٗا وَلَوِ ٱفۡتَدَىٰ بِهِۦٓۗ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ وَمَا لَهُم مِّن نَّٰصِرِينَ ٩١\nعن أبي عمران قال: سمعت أنس بن مالك عن النبي -صلى الله عليه وسلم- قال: «يقول الله لأهون أهل النار عذابًا يوم القيامة: لو أن لك ما في الأرض من شيء أكنت تفدي به؟ فيقول: نعم، فيقول: أردت منك أهون من ذلك وأنت في صلب آدم: أن لا تشرك بي شيئًا؛ فأبيت إلا أن تشرك بي». البغوي: ١/٣٨٠.\nماذا يقال لأهون أهل النار عذابًا يوم القيامة؟"],[62,"§آل عمران\nwords\nإِسرَائِيلَهُوَ نَبِيُّ اللهِ يَعقُوبُ بنُ إِسحَاقَ عليهما السلام.\nبِبَكَّةَبِمَكَّةَ.\nمَقَامُ إِبرَاهِيمَالحَجَرُ الَّذِي كَانَ يَقِفُ عَلَيهِ حِينَ كَانَ يَرفَعُ القَوَاعِدَ مِنَ البَيتِ.\ndeeds\nحدّد شيئًا تحبه، وأنفقه في سبيل الله تعالى لعلك تنال درجة الأبرار.\nاستعن بالله، وأكثر من الدعاء، ثم حدد خطوات تذلل فيها العقبات للوصول إلى بيت الله الحرام في عمرة أو حج؛ فإن الله تعالى عند ظن عبده به.\nخالِف اليهود والنصارى بإعفاء لحيتك وحف شاربك، وجعل لباسك فوق الكعب، والنساء تخفي زينتها عن غير المحارم بالحجاب الكامل.\nguid\nلن يبلغ العبد البر حتى ينفق من أمواله المحبوبة إليه.\nصد الناس عن الإيمان إنَّما هو من أعمال أهل الكفر والضلال.\nاحذر من طاعة الكافرين في الدين والعقيدة والفكر؛ فإنهم لا يجلبون عليك إلا الغفلة والفساد.\nrefl\nلَن تَنَالُواْ ٱلۡبِرَّ حَتَّىٰ تُنفِقُواْ مِمَّا تُحِبُّونَۚ\nفما كان أحب إلى المرء إذا تقرب به إلى الله تعالى كان أفضل له من غيره؛ وإن استويا في القيمة. ابن تيمية: ٢/١٠٨.\nما أفضل ما تتقرب به إلى الله تعالى من أموالك؟\nكُلُّ ٱلطَّعَامِ كَانَ حِلّٗا لِّبَنِيٓ إِسۡرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسۡرَٰٓءِيلُ عَلَىٰ نَفۡسِهِۦ مِن قَبۡلِ أَن تُنَزَّلَ ٱلتَّوۡرَىٰةُۚ قُلۡ فَأۡتُواْ بِٱلتَّوۡرَىٰةِ فَٱتۡلُوهَآ إِن كُنتُمۡ صَٰدِقِينَ ٩٣\nقال الزجاج: \"في هذه الآية أعظم دلالة لنبوة محمد نبينا -صلى الله عليه وسلم-؛ أخبرهم أنه ليس في كتابهم، وأمرهم أن يأتوا بالتوراة فأبوا؛ يعني عرفوا أنه قال ذلك بالوحي\". القرطبي: ٥/٢٠٤-٢٠٥.\nاذكر دليلًا من هذه الآية على نبوة نبينا -عليه الصلاة والسلام-.\nإِنَّ أَوَّلَ بَيۡتٖ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبَارَكٗا وَهُدٗى لِّلۡعَٰلَمِينَ ٩٦\nوإنَّما كانت الأولية موجبة التفضيل؛ لأن مواضع العبادة لا تتفاضل من جهة العبادة -إذ هي في ذلك سواء- ولكنها تتفاضل بما يحف بذلك من طول أزمان التعبد فيها، وبنسبتها إلى بانيها، وبحسن المقصد في ذلك. ابن عاشور: ٤/١٥.\nلماذا كانت أولية الكعبة على بقية المساجد موجبة لتفضيلها؟\nإِنَّ أَوَّلَ بَيۡتٖ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبَارَكٗا وَهُدٗى لِّلۡعَٰلَمِينَ ٩٦\nأي كثير الخير لما أنه يضاعف فيه ثواب العبادة... وقيل: لأنه يغفر فيه الذنوب لمن حجه وطاف به واعتكف عنده. و... يجوز أن تكون بركته ما ذكر في قوله تعالى: ﴿يُجۡبَىٰٓ إِلَيۡهِ ثَمَرَٰتُ كُلِّ شَيۡءٍ﴾ [القصص: ٥٧]، وقيل: بركته دوام العبادة فيه ولزومها. الألوسي: ٤/٥.\nبيّن بعض مظاهر البركة في البيت الحرام.\nفِيهِ ءَايَٰتُۢ بَيِّنَٰتٞ مَّقَامُ إِبۡرَٰهِيمَۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ\n﴿فِيهِ ءَايَٰتُۢ بَيِّنَٰتٌ﴾: آيات البيت كثيرة؛ منها: الحجر الذي هو مقام إبراهيم، وهو الذي قام عليه حين رفع القواعد من البيت، فكان كلما طال البناء ارتفع به الحجر في الهواء حتى أكمل البناء، وغرقت قدم إبراهيم في الحجر كأنها في طين وذلك الأثر باق إلى اليوم، ومنها: أن الطيور لا تعلوه، ومنها: إهلاك أصحاب الفيل، ورد الجبابرة عنه، ونبع زمزم لهاجر أم إسماعيل بهمز جبريل بعقبه، وحفر عبد المطلب بعد دثورها، وأن ماءها ينفع لما شُرب له، إلى غير ذلك. ابن جزي: ١/١٥٣.\nعدِّد بعض آيات البيت الحرام؟\nوَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلۡبَيۡتِ مَنِ ٱسۡتَطَاعَ إِلَيۡهِ سَبِيلٗاۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ ٩٧\nمن لم يحُجه مع الاستطاعة كفر بالنعمة إن كان معترفًا بالوجوب، وبالمروق من الدين إن جحد. البقاعي: ٢/١٢٨.\nما المقصود بالكفر في حق من لم يحج؟\nوَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلۡبَيۡتِ\nأفعال الله تعالى وأحكامه لا بد فيها من حكمة ومصلحة، وهو مسلَّم؛ لكن لا نسلم أنه لا بد أن تظهر هذه المصلحة لنا؛ إذ الحكيم لا يلزمه إطلاع من دونه على وجه الحكمة. الألوسي: ٤/١١.\nهل في كل أوامر الله لنا حكمة؟ وهل يلزم أن نعرف هذه الحكمة؟"],[63,"§آل عمران\nwords\nشَفَاحَافَّةِ.\ndeeds\nاكتب رسالة عن فوائد الاجتماع، وأضرار الاختلاف.\nاشكر أحد المشتغلين بالأمر بالمعروف والنهي عن المنكر ممن تعرفهم، وادع له.\nاحرص اليوم على الأمر بمعروف، والنهي عن منكر؛ لتدخل في عباد الله المفلحين.\nguid\nالمداومة على تلاوة القرآن وتدبره، وتأمل السنة النبوية، والعمل بهما من أعظم أسباب الثبات.\nاحذر أن تموت وقد بدَّلت وغيرت دين الله تعالى، وأكثر من دعاء: \"يا مقلب القلوب ثبت قلبي على دينك\".\nالخلاف المبني على الهوى شر على الفرد والمجتمع.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ ١٠٢\nقال السلف -ابن مسعود وغيره؛ كالحسن، وعكرمة، وقتادة، ومقاتل-: \"حق تقاته: أن يطاع فلا يعصى، وأن يشكر فلا يكفر، وأن يذكر فلا ينسى\". ابن تيمية:٢/١١٦.\nما المقصود بتقوى الله تعالى حق تقاته؟\nوَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ ١٠٢\nأي: حافظوا على الإسلام في حال صحكتم وسلامتكم لتموتوا عليه؛ فإن الكريم قد أجرى عادته بكرمه أنه من عاش على شيء مات عليه، ومن مات على شيء بُعث عليه. ابن كثير: ١/٣٦٦.\nأهم الواجبات في حياة الإنسان المبادرة إلى الالتزام والمحافظة عليه، فلماذا؟\nوَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعٗا وَلَا تَفَرَّقُواْۚ\n(جميعًا): لا تَدَعوا أحدًا منكم يشذ عنها، بل كلما عثرتم على أحد فارقها -ولو قيد شبر- فردوه إليها، ولا تناظروه، ولا تهملوا أمره، ولا تغفلوا عنه؛ فيختل النظام، وتتعبوا على الدوام، بل [لن] تزالوا كالرابط ربطًا شديدًا حزمة نبل بحبل، لا يدع واحدة منها تنفرد عن الأخرى. البقاعي: ٢/١٣١.\nما دلالة كلمة (جميعًا) في الأمر بالاعتصام في الآية؟\nوَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعٗا وَلَا تَفَرَّقُواْۚ\nوليس فيه دليل على تحريم الاختلاف في الفروع؛ فإن ذلك ليس اختلافًا؛ إذ الاختلاف ما يتعذر معه الائتلاف والجمع، وأمَّا حكم مسائل الاجتهاد فإن الاختلاف فيها بسبب استخراج الفرائض، ودقائق معاني الشرع، وما زالت الصحابة يختلفون في أحكام الحوادث، وهم مع ذلك متآلفون. القرطبي: ٥/٢٤١.\nهل كل اختلاف في وجهات النظر يعتبر تفرقًا وتمزقًا؟\nوَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ\nفي هذه الآية ما يدل أن الله يحب من عباده أن يذكروا نعمته بقلوبهم وألسنتهم؛ ليزدادوا شكرًا له ومحبة، وليزيدهم من فضله وإحسانه، وإن من أعظم ما يذكر من نعمه نعمة الهداية إلى الإسلام. السعدي: ١٤٢.\nكيف يذكر المؤمن نعمة ربه؟ وما فائدة هذا الذكر؟\nوَلۡتَكُن مِّنكُمۡ أُمَّةٞ يَدۡعُونَ إِلَى ٱلۡخَيۡرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ١٠٤\nالناس في تغيير المنكر والأمر بالمعروف على مراتب: ففرض العلماء فيه: تنبيه الحكام والولاة، وحملهم على جادة العلم، وفرض الولاة تغييره بقوتهم وسلطانهم... وفرض سائر الناس: رفعه إلى الحكام والولاة بعد النهي عنه قولًا؛ وهذا في المنكر الذي له دوام، وأمَّا إن رأى أحد نازلةً بديهةً من المنكر؛ كالسلب والزنى ونحوه، فيغيرها بنفسه بحسب الحال والقدرة. ابن عطية: ١/٤٨٦.\nبيّن مراتب الناس في الأمر بالمعروف والنهي عن المنكر.\nوَأَمَّا ٱلَّذِينَ ٱبۡيَضَّتۡ وُجُوهُهُمۡ فَفِي رَحۡمَةِ ٱللَّهِۖ هُمۡ فِيهَا خَٰلِدُونَ ١٠٧\nهؤلاء اسودت وجوههم بما في قلوبهم من الخزي والهوان والذلة والفضيحة، وأولئك ابيضت وجوههم لما في قلوبهم من البهجة والسرور والنعيم والحبور الذي ظهرت آثاره على وجوههم. السعدي: ١٤٣.\nما سبب ابيضاض وجوه المسلمين واسوداد وجوه الكافرين؟"],[64,"§آل عمران\nwords\nثُقِفُواوُجِدُوا.\nبِحَبلٍبِعَهدٍ.\nالمَسكَنَةُفَقرُ النَّفسِ، وَشُحُّهَا.\nفَلَن يُكفَرُوهُفَلَن يَضِيعَ عِندَ اللهِ.\ndeeds\nمُرِ اليوم بمعروف، أو انْهَ عن منكر.\nتذكر معصية أنت متساهل بها، وابتعد عنها لكي لا تقع في الذلة والمسكنة.\nأرسل رسالة تحذر فيها من أذية العلماء والصالحين؛ فهم ورثة الأنبياء.\nguid\nتذكر أن خيرية هذه الأمة المسلمة أتت من الأمر بالمعروف والنهي عن المنكر، والإيمان بالله.\nالإنصاف في الحكم على المجموعات والأفراد مأمور به في الشرع.\nإذا بدأ القتال بان ضعف العدو.\nrefl\nكُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ\nمن سره أن يكون من هذه الأمة فليؤَدِّ شرط الله فيها... ومن لم يتصف بذلك أشبه أهل الكتاب الذين ذمهم الله بقوله: ﴿كَانُواْ لَا يَتَنَاهَوۡنَ عَن مُّنكَرٖ فَعَلُوهُ﴾ [المائدة: ٧٩]. ابن كثير: ١/٣٧٤.\nذكرت الآية ميزة لهذه الأمة على بقية الأمم، فما هي؟\nكُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ\nوأصل (المعروف) كل ما كان معروفًا فعله، جميلًا مستحسنًا، غير مستقبح في أهل الإيمان بالله، وإنَّما سميت طاعة الله معروفًا؛ لأنه مما يعرفه أهل الإيمان، ولا يستنكرون فعله. وأصل (المنكر) ما أنكره الله، ورأوه قبيحًا فعله؛ ولذلك سميت معصية الله منكرًا؛ لأن أهل الإيمان بالله يستنكرون فعلها، ويستعظمون ركوبها. الطبري: ٧/١٠٥.\nما المقصود بالمعروف وما المقصود بالمنكر؟\nكُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ\nفالجهاد للكفَّار أصلح من هلاكهم بِعَذَاب سَمَاء من وُجُوه؛ أَحدهَا: أَن ذَلِك أعظم فِي ثَوَاب المُؤمنِينَ وأجرهم وعلو درجاتهم؛ لما يَفعَلُونَهُ من الجِهَاد فِي سَبِيل الله لأن تكون كلمة الله هِيَ العليا، وَيكون الدِّين كُله لله. الثَّانِي: أَن ذَلِك أَنفَع للكفَّار أيضًا؛ فَإِنَّهُم قد يُؤمنُونَ من الخَوف، وَمن أُسِر مِنهُم وسِيم من الصغار يسلم أيضًا، وَهَذَا من معنى قَوله تَعَالَى: ﴿كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ﴾؛ قَالَ أَبُو هُرَيرَة: \"وكنتم خير النَّاس للنَّاس؛ تأتون بهم فِي الأقياد والسلاسل حَتَّى تدخلوهم الجنَّة\"، فَصَارَت الأمة بذلك خير أمة أخرجت للنَّاس. ابن تيمية: ٢/١٢٢.\nجهاد المسلمين للكفار من أوجه خيرية الأمة، بين ذلك.\nضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ أَيۡنَ مَا ثُقِفُوٓاْ إِلَّا بِحَبۡلٖ مِّنَ ٱللَّهِ وَحَبۡلٖ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِ وَضُرِبَتۡ عَلَيۡهِمُ ٱلۡمَسۡكَنَةُۚ\nولما أخبر عنهم -سبحانه وتعالى- بهذا الذل أتبعه الإخبار بأنه في كل زمان وكل مكان معاملة منه لهم بضد ما أرادوا؛ فعوضهم عن الحرص على الرئاسة إلزامهم الذلة، وعن الإخلاد إلى المال إسكانهم المسكنة، وأخبر أن ذلك لهم طوق الحمامة؛ غير مزائلهم إلى آخر الدهر، باق في أعقابهم. البقاعي: ٢/١٣٦.\nعوقبت اليهود بالذلة والمسكنة على معصيتين وقعوا فيهما، فما هما؟\nوَيَقۡتُلُونَ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖۚ\nأي: يقابلون أنبياء الله الذين يحسنون إليهم أعظم إحسان بأشر مقابلة؛ وهو القتل، فهل بعد هذه الجراءة والجناية شيء أعظم منها؟ السعدي:١٤٣.\nمقابلة المصلحين بالإساءة والأذى صفة قديمة للمفسدين، وضح ذلك من الآية.\nلَيۡسُواْ سَوَآءٗۗ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةٞ قَآئِمَةٞ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ وَهُمۡ يَسۡجُدُونَ ١١٣\nوقيام الليل لقراءة العلم المبتغى به وجه الله داخل في هذه الآية، وهو أفضل من التنفل لمن يرجى انتفاع المسلمين بعلمه. ابن عطية: ١/٤٩٣.\nمتى تكون مذاكرة العلم ليلًا أفضل من قيام الليل بالنوافل؟\nوَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِۖ وَأُوْلَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ ١١٤\n﴿وَيُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِۖ﴾ أي: يبادرون إلى فعل الخيرات والطاعات خوف الفوات بالموت مثلًا، أو يعملون الأعمال الصالحة راغبين فيها غير متثاقلين؛ لعلمهم بجلالة موقعها وحسن عاقبتها. وهذه صفة جامعة لفنون الفضائل والفواضل، وفي ذكرها تعريض بتباطؤ اليهود وتثاقلهم عن ذلك. الألوسي: ٤/٣٤.\nما الذي دفع المؤمنين إلى المسارعة بالخيرات؟"],[65,"§آل عمران\nwords\nصِرٌّبَردٌ شَدِيدٌ.\nلاَ يَألُونَكُم خَبَالًالاَ يُقَصِّرُونَ فِي إِفسَادِ حَالِكُم.\nوَدُّوا مَا عَنِتُّمأَحَبُّوا مَشَقَّتَكُمُ الشَّدِيدَةَ.\nأُولاَءِهَؤُلاَءِ.\nغَدَوتَخَرَجتَ مِن أَوَّلِ النَّهَارِ.\nتُبَوِّئُتُنَزِّلُ.\ndeeds\nاكتب رسالة عن أموال المشركين ومظاهرهم، وأنها لا تغني عنهم شيئًا.\nقوِّم اليوم جلساءك، وقرّب من يعينك على عبادة الله، واستبدل من يبعدك عن ذكر الله.\nهنِّئ أخًا لك حصلت له نعمة، وواسِ أخًا لك حصلت له مصيبة؛ فهذه صفة المؤمنين، عكس صفة المنافقين.\nguid\nالمعاصي سبب المصائب.\nالمسلم العاقل لا يطلب النصيحة إلا من المؤمنين الصادقين.\nتذكر دائمًا أن النصر على الأعداء والأمن من مكرهم مشروط بالتقوى والصبر.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ بِطَانَةٗ مِّن دُونِكُمۡ لَا يَأۡلُونَكُمۡ خَبَالٗا وَدُّواْ مَا عَنِتُّمۡ قَدۡ بَدَتِ ٱلۡبَغۡضَآءُ مِنۡ أَفۡوَٰهِهِمۡ وَمَا تُخۡفِي صُدُورُهُمۡ أَكۡبَرُۚ\nنهي عن استخلاص الكفار وموالاتهم، وقيل لعمر -رضي الله عنه-: إن هنا رجلًا من النصارى لا أحد أحسن خطًّا منه، أفلا يكتب عنك؟ قال: \"إذًا أتخذ بطانة من دون المؤمنين\". ﴿لَا يَأۡلُونَكُمۡ خَبَالًا﴾ أي: لا يقصرون في إفسادكم. ابن جزي: ١/١٥٩.\nما رأيك بمن يتخذ مستشارين أو موظفين من أعداء الإسلام؟ وما عاقبة ذلك؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ بِطَانَةٗ مِّن دُونِكُمۡ لَا يَأۡلُونَكُمۡ خَبَالٗا\nوإنَّما العاقل من إذا ابتُلِيَ بمخالطة العدو أن تكون مخالطة في ظاهره، ولا يطلعه من باطنه على شيء، ولو تَمَلَّقَ له وأقسم أنه من أوليائه. السعدي: ١٤٤.\nبعض المسلمين قد يضطر إلى مخالطة غير المسلمين، فماذا يفعل؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ بِطَانَةٗ مِّن دُونِكُمۡ لَا يَأۡلُونَكُمۡ خَبَالٗا وَدُّواْ مَا عَنِتُّمۡ قَدۡ بَدَتِ ٱلۡبَغۡضَآءُ مِنۡ أَفۡوَٰهِهِمۡ وَمَا تُخۡفِي صُدُورُهُمۡ أَكۡبَرُۚ\nأحبوا مشقتكم الشديدة وضرركم، وظهرت أمارات العداوة لكم من فلتات ألسنتهم وفحوى كلماتهم، وما تخفي صدورهم من البغضاء أكبر؛ أي أعظم مما بَدَا؛ لأنه كان عن فلتة، ومثله لا يكون إلا قليلًا. الألوسي: ٤/٣٨.\nلماذا نهى الله تعالى عن اتخاذ أعوان من المشركين؟\nهَٰٓأَنتُمۡ أُوْلَآءِ تُحِبُّونَهُمۡ وَلَا يُحِبُّونَكُمۡ وَتُؤۡمِنُونَ بِٱلۡكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمۡ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ عَضُّواْ عَلَيۡكُمُ ٱلۡأَنَامِلَ مِنَ ٱلۡغَيۡظِۚ قُلۡ مُوتُواْ بِغَيۡظِكُمۡۗ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ١١٩\nفالعجب من محبة المؤمنين إياهم في حال بغضهم المؤمنين. ابن عاشور: ٤/٦٥.\nمن أي شيء كان التعجب في الآية الكريمة؟\nإِن تَمۡسَسۡكُمۡ حَسَنَةٞ تَسُؤۡهُمۡ وَإِن تُصِبۡكُمۡ سَيِّئَةٞ يَفۡرَحُواْ بِهَاۖ\nمن كانت هذه صفته من شدة العداوة والحقد والفرح بنزول الشدائد على المؤمنين؛ لم يكن أهلًا لأن يُتَّخذ بطانةً، لا سيما في هذا الأمر الجسيم من الجهاد الذي هو مِلاك الدنيا والآخرة. القرطبي: ٥/٢٨١.\nما الحكمة من منع اتخاذ الكفار والمنافقين بطانة؛ أي مستشارين أو موظفين؟\nوَإِن تَصۡبِرُواْ وَتَتَّقُواْ لَا يَضُرُّكُمۡ كَيۡدُهُمۡ شَيۡٔاًۗ إِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ مُحِيطٞ ١٢٠\nفالصبر يدخل فيه الصبر على المقدور، والتقوى يدخل فيها فعل المأمور وترك المحظور؛ فمن رُزق هذا وهذا فقد جمع له الخير، بخلاف من عكس فلا يتقي الله، بل يترك طاعته متبعًا لهواه، ويحتج بالقدر، ولا يصبر إذا ابتلي، ولا ينظر حينئذ إلى القدر، فإن هذا حال الأشقياء. ابن تيمية: ٢/١٣٣.\nبيّن حال من رزقه الله تعالى الصبر والتقوى، ومن حرمهما.\nوَإِذۡ غَدَوۡتَ مِنۡ أَهۡلِكَ تُبَوِّئُ ٱلۡمُؤۡمِنِينَ مَقَٰعِدَ لِلۡقِتَالِۗ\nأي: تُنَزِّلهم وترتبهم؛ كل في مقعده اللائق به، وفيها أعظم مدح للنبي -صلى الله عليه وسلم-؛ حيث هو الذي يباشر تدبيرهم وإقامتهم في مقاعد القتال؛ وما ذاك إلا لكمال علمه ورأيه، وسداد نظره، وعلو همته؛ حيث يباشر هذه الأمور بنفسه وشجاعته الكاملة، صلوات الله وسلامه عليه. السعدي: ١٤٥.\nفي الآية مدحٌ للنبي -صلى الله عليه وسلم-، وضِّح ذلك."],[66,"§آل عمران\nwords\nأَن تَفشَلاَتَجبُنَا، وَتَضعُفَا.\nفَورِهِم هَذَاسَاعَتِهِم هَذِهِ.\nمُسَوِّمِينَمُعَلِّمِينَ أَنفُسَهُم وَخُيُولَهُم بِعَلاَمَاتٍ وَاضِحَاتٍ.\nيَكبِتَهُميُخزِيَهُم.\ndeeds\nابدأ خطوات في الإصلاح بين شخصين أو مجموعتين متخاصمتين.\nبشّر مسلمًا بخبر يفرحه.\nأرسل رسالة تحذّر فيها المسلمين من مخاطر الربا.\nguid\nتقوى الله تعالى -بالعمل بأوامره واجتناب نواهيه- هي الشكر الواجب على العبد.\nاصبر واتق الله يمدك الله بأسبابٍ من عنده خافية عليك.\nاحذر الربا وأنواعه، وحذِّر من حولك من هذا الذنب العظيم.\nrefl\nوَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرٖ وَأَنتُمۡ أَذِلَّةٞۖ فَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ ١٢٣\nلما ذكر تعالى قصة أُحُد أتبعها بذكر قصة بدر؛ وذلك لأن المسلمين يوم بدر كانوا في غاية الضعف عددًا وعتادًا، والكفار كانوا في غاية الشدة والقوة، ثم إنه تعالى نصر المسلمين على الكافرين، فصار ذلك من أقوى الدلائل على أن ثمرة التوكل عليه تعالى والصبر والتقوى هو النصر والمعونة والتأييد. القاسمي: ٢/٤٠٢.\nما وجه ذكر غزوة بدر عقب الحديث عن غزوة أُحُد؟\nبَلَىٰٓۚ إِن تَصۡبِرُواْ وَتَتَّقُواْ وَيَأۡتُوكُم مِّن فَوۡرِهِمۡ هَٰذَا يُمۡدِدۡكُمۡ رَبُّكُم بِخَمۡسَةِ ءَالَٰفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُسَوِّمِينَ ١٢٥\nفبيّن أنه مع الصبر والتقوى يمدهم بالملائكة، وينصرهم على أعدائهم الذين يقاتلونهم. ابن تيمية: ٢/١٣٥.\nالصبر والتقوى سببان لنزول الملائكة لنصرة المؤمن، بيّن ذلك.\nوَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَطۡمَئِنَّ قُلُوبُكُم بِهِۦۗ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ١٢٦\nأي: وما أنزل الله الملائكة وأعلمكم بإنزالها إلا بشارة لكم، وتطييبًا لقلوبكم، وتطمينًا، وإلا فإنما النصر من عند الله، الذي لو شاء لانتصر من أعدائه بدونكم، ومن غير احتياج إلى قتالكم لهم؛ كما قال تعالى بعد أمره المؤمنين بالقتال: ﴿ذَٰلِكَۖ وَلَوۡ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنۡهُمۡ وَلَٰكِن لِّيَبۡلُوَاْ بَعۡضَكُم بِبَعۡضٖ﴾ [محمد: ٤]. ابن كثير: ١/٣٨٠.\nهل ربنا سبحانه بحاجة للمجاهدين؟ وما الذي يفيده المجاهد من ذلك؟\nوَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَطۡمَئِنَّ قُلُوبُكُم بِهِۦۗ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ١٢٦\n﴿وَمَا جَعَلَهُ ٱللَّهُ﴾ يعني: هذا الوعد والمدد، ﴿إِلَّا بُشۡرَىٰ لَكُمۡ﴾ أي: بشارة لتستبشروا به، (ولتطمئن): ولتسكن، ﴿قُلُوبُكُم بِهِۦۗ﴾ فلا تجزعوا من كثرة عدوكم وقلة عددكم، ﴿وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ﴾ يعني: لا تحيلوا بالنصر على الملائكة والجند؛ فإن النصر من الله تعالى، فاستعينوا به، وتوكلوا عليه؛ لأن العز والحكم له. البغوي: ١/٤١٥.\nما المصدر الوحيد للنصر؟\nوَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ١٢٦\nفلا تعتمدوا على ما معكم من الأسباب، بل الأسباب فيها طمأنينة لقلوبكم، وأمَّا النصر الحقيقي الذي لا معارض له فهو مشيئة الله لنصر من يشاء من عباده؛ فإنه إن شاء نصر من معه الأسباب كما هي سنته في خلقه، وإن شاء نصر المستضعفين الأذلين؛ ليبين لعباده أن الأمر كله بيديه، ومرجع الأمور إليه. السعدي: ١٤٦.\nما فائدة إخبار المسلمين بأن النصر من عند الله -سبحانه وتعالى-؟\nلَيۡسَ لَكَ مِنَ ٱلۡأَمۡرِ شَيۡءٌ\nوفي هذه الآية ما يدل على أن اختيار الله غالب على اختيار العباد، وأن العبد- وإن ارتفعت درجته وعلا قدره- قد يختار شيئًا وتكون الخيرة والمصلحة في غيره، وأن الرسول -صلى الله عليه وسلم- ليس له من الأمر شيء، فغيره من باب أولى؛ ففيها أعظم رد على من تعلق بالأنبياء أو غيرهم من الصالحين وغيرهم، وأن هذا شرك في العبادة، ونقص في العقل؛ يتركون مَن الأمر كله له، ويَدعُون من لا يملك من الأمر مثقال ذرة. السعدي: ١٤٧.\nمن خلال هذه الآية: كيف ترد على من تعلق بالأنبياء والصالحين من دون الله؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُواْ ٱلرِّبَوٰٓاْ أَضۡعَٰفٗا مُّضَٰعَفَةٗۖ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ ١٣٠\nاجعلوا بينكم وبين مخالفة نهيه عن الربا وقاية؛ بالإعراض عن مطلق محبة الدنيا والإقبال عليها؛ لتكونوا على رجاء من الفوز بالمطالب؛ فمن له مِلك الوجود ومُلكه فإنه جدير بأن يعطيكم من مِلكه إن اتقيتم، ويمنعكم إن تساهلتم. البقاعي: ٢/١٥٢.\nما العلاقة بين النهي عن الربا والأمر بالتقوى؟"],[67,"§آل عمران\nwords\nالسَّرَّاءِ وَالضَّرَّاءِاليُسرِ، وَالعُسرِ.\nوَلاَ تَهِنُوالاَ تَضعُفُوا.\nقَرحٌجُرحٌ.\nنُدَاوِلُهَانُصَرِّفُهَا.\ndeeds\nاسبق اليوم غيرك إلى عمل صالح رجاء أن تدخل في هذه الآية.\nتصدق بصدقة سواء كنت مغتنيًا أو محتاجًا.\nاستغفر الله تعالى سبعين مرةً في يومك وليلتك.\nguid\nالمتقون هم أهل الجنة فاجتهد في الاتصاف بصفاتهم.\nفضل العفو عن الناس.\nإياك والهوان والـذلة؛ فالمـؤمن عزيز غالب بهذا الدين.\nrefl\nٱلَّذِينَ يُنفِقُونَ فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ ١٣٤\nولمَّا ذكر أشق ما يترك ويبذل؛ وهو المال، أتبعه أشق ما يحبس؛ فقال: (والكاظمين) أي: الحابسين (الغيظ) عن أن ينفذوه بعد أن امتلأوا منه. البقاعي: ٢/١٥٧.\nما دلالة الإتيان بكظم الغيظ بعد الإنفاق؟\nٱلَّذِينَ يُنفِقُونَ فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ ١٣٤\nفالكاظم للغيظ والعافي عن الناس قد أحسن إلى نفسه وإلى الناس؛ فإن ذلك عمل حسنة مع نفسه، ومع الناس، ومن أحسن إلى الناس فإلى نفسه... قَالَ تَعَالَى: ﴿إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَا﴾ [الإسراء:٧]. ابن تيمية: ٢/١٤٠-١٤١.\nمن المستفيد الأول من كظمك للغيظ وعفوك عن الناس؟ وكيف ذلك؟\nوَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ ١٣٤\nيعني: والجارعين الغيظ عند امتلاء نفوسهم منه؛ يقال منه: كظم فلان غيظه: إذا تجرَّعه، فحفظ نفسه من أن تُمضي ما هي قادرةٌ على إمضائه. الطبري: ٧/٢١٤.\nاستخرج من الآية صفة من صفات المسارعين إلى المغفرة والجنة.\nقَدۡ خَلَتۡ مِن قَبۡلِكُمۡ سُنَنٞ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ ١٣٧\nوفي الآية دلالة على أهمية علم التاريخ؛ لأن فيه فائدة السير في الأرض، وهي معرفة أخبار الأوائل، وأسباب صلاح الأمم، وفسادها. ابن عاشور: ٤/٩٧.\nللقراءة في التاريخ ومعرفة أحوال الأمم أهميتها، بيّن ذلك من الآية الكريمة.\nهَٰذَا بَيَانٞ لِّلنَّاسِ وَهُدٗى وَمَوۡعِظَةٞ لِّلۡمُتَّقِينَ ١٣٨\nفالبيان يعمّ كل من فَقِهَهُ، والهدى والموعظة للمتقين. ابن تيمية: ٢/١٤٣.\nالبيان للناس كلهم، والهدى والموعظة للمتقين فقط، بيّن ذلك من الآية.\nوَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِينَ ١٣٩\n﴿وَلَا تَهِنُواْ﴾ أي: في جهاد أعدائكم الذين هم أعداء الله؛ فالله معكم عليهم، وإن ظهروا يوم أُحُد نوع ظهور؛ فسترون إلى من يؤول الأمر، ﴿وَلَا تَحۡزَنُواْ﴾ أي: على ما أصابكم منهم، ولا على غيره مما عساه ينوبكم، والحال أنكم (أنتم الأعلون) أي: في الدارين؛ ﴿إِن كُنتُم مُّؤۡمِنِينَ﴾. البقاعي: ٢/٥٩.\nهل الهزيمة المؤقتة للمؤمنين تنافـي علوهم؟ وضح ذلك.\nوَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِينَ ١٣٩\nيجب بهذه الآية أن لا يوادَعَ العدو ما كانت للمسلمين قوةٌ، فإن كانوا في قُطرٍ ما على غير ذلك؛ فينظر الإمام لهم بالأصلح. ابن عطية: ١ / ٥١٣.\nمتى تصح الموادعة من المسلمين للكفار؟"],[68,"§آل عمران\nwords\nانقَلَبتُم عَلَى أَعقَابِكُمرَجَعتُم عَن دِينِكُم.\nرِبِّيُّونَجُمُوعٌ كَثِيرَةٌ.\ndeeds\nاسأل الله تعالى الشهادة بصدق.\nاستمع لمحاضرة، أو اقرأ كتابًا عن الموت.\nاقرأ هذه الآية، ثم ابدأ بتحديد مشروع حياتك.\nguid\nمن حكمة الله تعالى في نزول البلايا: التمحيص والاختبار، وتمييز الخبيث من الطيب.\nلا يوصل إلى الراحة إلا بقلة الراحة، ولا يدرك النعيم إلا بقلة النعيم.\nالجهاد وخوض المعارك لا يقدم أجل العبد، والفرار من الجهاد لا يؤخره أيضًا.\nrefl\nوَلَقَدۡ كُنتُمۡ تَمَنَّوۡنَ ٱلۡمَوۡتَ مِن قَبۡلِ أَن تَلۡقَوۡهُ\nفي هذه الآية دليل على أنه لا يُكره تمني الشهادة، ووجه الدلالة: أن الله تعالى أقرهم على أمنيتهم، ولم يُنكر عليهم، وإنَّما أنكر عليهم عدم العمل بمقتضاها. السعدي: ١٥٠.\nهل تمني الشهادة مثل تمني الموت؟ وضح ذلك من خلال هذه الآية.\nوَمَا مُحَمَّدٌ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُۚ أَفَإِيْن مَّاتَ أَوۡ قُتِلَ ٱنقَلَبۡتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡۚ\nوفي هذه الآية أعظم دليل على فضيلة الصديق الأكبر أبي بكر وأصحابه؛ الذين قاتلوا المرتدين بعد رسول الله -صلى الله عليه وسلم-. السعدي: ١٥١.\nفي قتال أبي بكر ومن معه من الصحابة للمرتدين دليل على فهم عظيم وحكمة، وضح ذلك.\nوَمَا مُحَمَّدٌ إِلَّا رَسُولٞ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُۚ أَفَإِيْن مَّاتَ أَوۡ قُتِلَ ٱنقَلَبۡتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡۚ\nوفي هذه الآية الكريمة إرشاد من الله تعالى لعباده أن يكونوا بحالة لا يزعزعهم عن إيمانهم أو عن بعض لوازمه فقدُ رئيس -ولو عظم-، وما ذاك إلا بالاستعداد في كل أمر من أمور الدين بعدةِ أناسٍ من أهل الكفاءة فيه؛ إذا فُقد أحدهم قام به غيره. السعدي: ١٥١.\nفي الآية إرشادٌ إلى قاعدة مهمة في الإدارة والقيادة، وضِّحها.\nوَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ ١٤٦ وَمَا كَانَ قَوۡلَهُمۡ إِلَّآ أَن قَالُواْ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا\nفجمعوا بين الصبر والاستغفار، وهذا هو المأمور به في المصائب: الصبر عليها، والاستغفار من الذنوب التي كانت سببها. ابن تيمية: ٢/١٥٦.\nما المأمور به عند المصائب؟\nوَمَا كَانَ قَوۡلَهُمۡ إِلَّآ أَن قَالُواْ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ١٤٧\nعلموا أن الذنوب والإسراف من أعظم أسباب الخذلان، وأن التخلي منها من أسباب النصر، فسألوا ربهم مغفرتها. السعدي: ١٥١.\nلماذا سأل المجاهدون مغفرة الذنوب والإسراف في الأمر؟\nوَمَا كَانَ قَوۡلَهُمۡ إِلَّآ أَن قَالُواْ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ ١٤٧\nطلبوا الغفران أولًا ليستحقوا طلب النصر على الكافرين بترجحهم بطهارتهم عن الذنوب عليهم وهم محاطون بالذنوب. وفي طلبهم النصر -مع كثرتهم المفرطة التي دل عليها ما سبق- إيذان بأنهم لا ينظرون إلى كثرتهم، ولا يعولون عليها، بل يسندون ثبات أقدامهم إلى الله تعالى، ويعتقدون أن النصر منه -سبحانه وتعالى-. الألوسي: ٤/٨٥.\nلماذا طلب المجاهدون الغفران قبل طلبهم النصر؟ ولماذا طلبوا النصر مع كثرة عددهم؟\nفَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنۡيَا وَحُسۡنَ ثَوَابِ ٱلۡأٓخِرَةِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ ١٤٨\n(فآتاهم الله) المحيط علمًا وقدرةً ﴿ثَوَابَ ٱلدُّنۡيَا﴾ أي: بأن قبل دعاءهم بالنصر، والغنى بالغنائم وغيرها، وحسن الذكر، وانشراح الصدر، وزوال شبهات الشر. ولما كان ثواب الدنيا -كيف ما كان- لا بد أن يكون بالكدر مشوبًا، وبالبلاء مصحوبًا -لأنها دار الأكدار- أعراه من وصف الحسن، وخَصَّ الآخرة به فقال: ﴿وَحُسۡنَ ثَوَابِ ٱلۡأٓخِرَةِۗ﴾. البقاعي: ٢/١٦٤.\nلماذا جاء وصف الحسن مع ثواب الآخرة فقط دون ثواب الدنيا؟"],[69,"§آل عمران\nwords\nتَحُسُّونَهُمتَقتُلُونَهُم.\nتُصعِدُونَتَصعَدُونَ فِي الجَبَلِ هَارِبِينَ.\nوَلاَ تَلوُونَلاَ تَلتَفِتُونَ.\ndeeds\nحدد ثلاثة من مظاهر التشبه بالكفار مما يفعله بعض الناس اليوم، وأرسلها في رسالة للتحذير من منهجهم.\nأرسل رسالة تحذر فيها أن رؤية المال هو اختبار للثبات على الدين والمبادئ، وهو سبب للخلاف والتنازع بين المسلمين على مر القرون.\nأصلح بين متخاصمين.\nguid\nالشرك بالله هو سبب الخوف والقلق والضيق في الحياة.\nلا تأمن على نفسك الفتنة ووقوع المعصية؛ فقد قال الله تعالى عن الصحابة.\nمن مكانة الصحابة -رضي الله عنهم- عند الله سبحانه أنه أخبر أنه عفا عنهم، وشهد لهم بالإيمان؛ مما زاد من غيظ أعدائهم من المنافقين وأتباعهم.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تُطِيعُواْ ٱلَّذِينَ كَفَرُواْ يَرُدُّوكُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ ١٤٩\nزجر المؤمنين عن متابعة الكفار؛ ببيان مضارها... بالنداء بوصفهم بالإيمان لتذكيرهم بحال ينافي تلك الطاعة؛ فيكون الزجر على أكمل وجه. روح المعاني ٤/٨٧.\nلماذا خاطب الله المؤمنين بلفظ الإيمان عند تحذيرهم من طاعة الكفار؟\nسَنُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ بِمَآ أَشۡرَكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗاۖ\nتخويف الكفار والمنافقين وإرعابهم هو من الله نصرة للمؤمنين. ابن تيمية: ٢/١٥٧-١٥٨.\nبيّن بعض جند الله المذكورين في الآية.\nسَنُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ بِمَآ أَشۡرَكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗاۖ\n﴿بِمَآ أَشۡرَكُواْ بِٱللَّهِ﴾ تعليل؛ أي: كان سبب إلقاء الرعب في قلوبهم إشراكهم. القرطبي: ٥/٣٥٧.\nبيّن كيف يكون الشرك سببًا للخوف والرعب.\nحَتَّىٰٓ إِذَا فَشِلۡتُمۡ وَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَعَصَيۡتُم مِّنۢ بَعۡدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَۚ\n(وتنازعتم) وقع النزاع بين الرماة؛ فثبت بعضهم كما أمروا، ولم يثبت بعضهم، (وعصيتم) أي: خالفتم ما أمرتم به من الثبوت. وجاءت المخاطبة في هذا لجميع المؤمنين -وإن كان المخالف بعضهم- وعظًا للجميع، وسترًا على من فعل. ابن جزي: ١/١٦١.\nلم جاء الخطاب في الآية للجميع مع كون المخالفة وقعت من بعضهم؟\nحَتَّىٰٓ إِذَا فَشِلۡتُمۡ وَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَعَصَيۡتُم\nلما ذكر الفشل عطف عليه ما هو سببه في الغالب؛ وهو التنازع والمعصية. البقاعي: ٢/١٦٨.\nلماذا عطف التنازع والمعصية على الفشل؟\nوَلَقَدۡ صَدَقَكُمُ ٱللَّهُ وَعۡدَهُۥٓ إِذۡ تَحُسُّونَهُم بِإِذۡنِهِۦۖ حَتَّىٰٓ إِذَا فَشِلۡتُمۡ وَتَنَٰزَعۡتُمۡ\nأي: ضعفتم وتراخيتم بالميل إلى الغنيمة خلاف ما تدعو إليه الهمم العوالي... فقد كانت العرب على حال جاهليتها تفاخر بالإقبال على الطعن والضرب في مواطن الحرب، والإعراض عن الغنائم. البقاعي: ٢/١٦٦.\nمن خلال الآية وضح ما الذي غيَّر سير معركة أُحُد من النصر للمسلمين إلى الهزيمة؟\nوَٱللَّهُ ذُو فَضۡلٍ عَلَى ٱلۡمُؤۡمِنِينَ ١٥٢\nومن فضله على المؤمنين: أنه لا يُقَدِّر عليهم خيرًا ولا مصيبة إلا كان خيرًا لهم؛ إن أصابتهم سراء فشكروا جازاهم جزاء الشاكرين، وإن أصابتهم ضراء فصبروا جازاهم جزاء الصابرين. السعدي: ١٥٢.\nما وجه ختم الآيات التي ذكرت فيها مصيبة المؤمنين بفضل الله سبحانه؟"],[70,"§آل عمران\nwords\nأَمَنَةًأَمنًا، وَعَدَمَ خَوفٍ.\nمَضَاجِعِهِممَصَارِعِهِم.\nغُزَّىغُزَاةً مُجَاهِدِينَ.\ndeeds\nذكِّر بعض أهل الابتلاء بحسن الظن بالله تعالى، وأنهم سيعلمون غدًا أن الله سبحانه قد أراد بهم خيرًا.\nاستغفر اليوم سبعين مرةً، واسأل الله حسن الخاتمة؛ فالموت قد يأتي فجأة، وفي مكان وزمان لا تتوقعه.\nقد يكون تقصيرك وبعدك عن الله تعالى بسبب ذنب فعلته، فأكثر اليوم من الصدقة، والاستغفار، والتوبة.\nguid\nمن إكرام الله تعالى لأوليائه أن ينزل الأمان في قلوبهم عند الحاجة.\nالذنب يولّد الذنب، والسيئة تولّد السيئة؛ وهذا ما يوجب التوبة من الذنب فورًا.\nالذنوب في أوقات السراء سببٌ لمزلة القدم عند الضراء.\nrefl\nثُمَّ أَنزَلَ عَلَيۡكُم مِّنۢ بَعۡدِ ٱلۡغَمِّ أَمَنَةٗ نُّعَاسٗا يَغۡشَىٰ طَآئِفَةٗ مِّنكُمۡۖ\nوقد استجدوا بذلك نشاطهم، ونسوا حزنهم؛ لأن الحزن تبتدئ خفته بعد أول نومة تعفيه، كما هو مشاهد في أحزان الموت وغيرها. ابن عاشور: ٤/١٣٣.\nما فائدة تنَزُّل النعاس على المجاهدين؟\nوَطَآئِفَةٞ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ\nكان غرض المنافقين لا المدافعة عن الدين؛ فهم إنَّما يطلبون خلاص أنفسهم، فعوقبوا على ذلك بأنه لم يحصل لهم الأمن المذكور. البقاعي: ٢/١٦٩.\nلماذا لم يأمن المنافقون كما أمن المؤمنون؟\nقُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ\nكنى بكون الغلبة لله تعالى عن كونها لأوليائه؛ لكونهم من الله سبحانه بمكان، أو أن القضاء أو التدبير له تعالى مخصوص به، لا يشاركه فيه غيره؛ فيفعل ما يشاء. الألوسي: ٤/٩٥.\nما دلالة قوله تعالى: ﴿قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ﴾؟\nيَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَيۡءٞ مَّا قُتِلۡنَا هَٰهُنَاۗ\nوهذا إنكار منهم وتكذيب بقدر الله، وتسفيه منهم لرأي رسول الله -صلى الله عليه وسلم- ورأي أصحابه، وتزكية منهم لأنفسهم، فرد الله عليهم بقوله: ﴿قُل لَّوۡ كُنتُمۡ فِي بُيُوتِكُمۡ﴾ التي هي أبعد شيء عن مظان القتل ﴿لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡۖ﴾ فالأسباب -وإن عظمت- إنَّما تنفع إذا لم يعارضها القدر والقضاء. السعدي: ١٥٣.\nما مدى شناعة هذه المقالة التي صدرت من المنافقين في ذلك اليوم؟\nإِنَّ ٱلَّذِينَ تَوَلَّوۡاْ مِنكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّيۡطَٰنُ بِبَعۡضِ مَا كَسَبُواْۖ\nإن القتال في الجهاد إنَّما هو بالأعمال، فمن كان أصبر في أعمال الطاعة كان أجلد على قتال الكفار. البقاعي:٢/١٧١.\nهل هناك علاقة بين ترك الجهاد والذنوب؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَكُونُواْ كَٱلَّذِينَ كَفَرُواْ وَقَالُواْ لِإِخۡوَٰنِهِمۡ إِذَا ضَرَبُواْ فِي ٱلۡأَرۡضِ أَوۡ كَانُواْ غُزّٗى لَّوۡ كَانُواْ عِندَنَا مَا مَاتُواْ وَمَا قُتِلُواْ لِيَجۡعَلَ ٱللَّهُ ذَٰلِكَ حَسۡرَةٗ فِي قُلُوبِهِمۡۗ\nنهى الله تعالى المؤمنين عن الكون مثل الكفار والمنافقين في هذا المعتقد الفاسد؛ الذي هو أن من سافر في تجارة ونحوها، ومن قاتل فقتل، لو قعد في بيته لعاش ولم يمت في ذلك الوقت الذي عرض فيه نفسه للسفر، أو للقتال. ابن عطية: ١/٥٣٠.\nيضعف الإيمان بالقدر عند الغافلين إذا سمعوا خبر مقتل المجاهدين، وضح ذلك.\nوَلَئِن قُتِلۡتُمۡ فِي سَبِيلِ ٱللَّهِ أَوۡ مُتُّمۡ لَمَغۡفِرَةٞ مِّنَ ٱللَّهِ وَرَحۡمَةٌ خَيۡرٞ مِّمَّا يَجۡمَعُونَ ١٥٧\n﴿وَلَئِن قُتِلۡتُمۡ﴾ أيها المؤمنون في سبيل الله؛ أي: في الجهاد، أو متم حتف الأنف؛ وأنتم متلبسون به فعلًا أو نيةً، ﴿لَمَغۡفِرَةٌ مِّنَ ٱللَّهِ وَرَحۡمَةٌ خَيۡرٌ مِّمَّا يَجۡمَعُونَ﴾ أي: الكفار من منافع الدنيا ولذاتها مدة أعمارهم؛ وهذا ترغيب للمؤمنين في الجهاد، وأنه مما يجب أن يتنافس فيه المتنافسون، وفيه تعزية لهم، وتسلية مما أصابهم في سبيل الله تعالى إثر إبطال ما عسى أن يثبطهم عن إعلاء كلمة الله تعالى. الألوسي: ٤/١٠٤.\nما علامة إرادة الخير بالإنسان؟ وضح ذلك من خلال الآية."],[71,"§آل عمران\nwords\nفَظًّاسَيِّئَ الخُلُقِ.\nيَغُلَّيَأخُذَ مِنَ الغَنِيمَةِ قَبلَ قِسمَتِهَا.\nبَاءَرَجَعَ.\ndeeds\nاسأل الله سبحانه أن يرزقك الرحمة بإخوانك، واللين لهم، وشاورهم ببعض أمورك، ودرب نفسك على هذه الصفات.\nحدد اليوم الأمور التي تسبب لك قلقًا في حياتك، ثم تأمل كثيرًا في صفات الله المناسبة لها؛ لتكون حافزًا لك للتوكل على الله سبحانه.\nحدد لك وردًا يوميًا من القرآن الكريم.\nguid\nالرحمة، والعفو، والتواضع، ولين الجانب؛ من أهم صفات الداعية.\nتذكر أن طلب النصر من غير الله خذلان، والمنصور من نصره الله، والمخذول من خذله الله -عز وجل-.\nلا تنس دائمًا أن الذنوب والمعاصي هي سبب الخسران والهزيمة وعدم التوفيق.\nrefl\nفَبِمَا رَحۡمَةٖ مِّنَ ٱللَّهِ لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِيظَ ٱلۡقَلۡبِ لَٱنفَضُّواْ مِنۡ حَوۡلِكَۖ\nلعل المراد بهذه الرحمة ربطه -سبحانه وتعالى- على جأشه -صلى الله تعالى عليه وسلم-، وتخصيصه له بمكارم الأخلاق، وجعل الرفق ولين الجانب مسببًا عن ربط الجأش؛ لأن من ملك نفسه عند الغضب كان كامل الشجاعة. الألوسي: ٤/١٠٥.\nما علامة رحمة الله بالعبد المذكورة في الآية؟\nوَشَاوِرۡهُمۡ فِي ٱلۡأَمۡرِۖ\nوقد قيل: إن الله أمر بها نبيه لتأليف قلوب أصحابه، وليقتدي به من بعده، وليستخرج بها منهم الرأي فيما لم ينزل فيه وحي من أمر الحروب، والأمور الجزئية، وغير ذلك؛ فغيره -صلى الله عليه وسلم- أولى بالمشورة. ابن تيمية: ٢/١٦١.\nبيّن بعض حِكَم الأمر للنبي -صلى الله عليه وسلم- بمشاورة أصحابه.\nوَشَاوِرۡهُمۡ فِي ٱلۡأَمۡرِۖ\nإشعار بمنزلة الصحابة، وأنهم كلهم أهل اجتهاد، وأن باطنهم مرضي عند الله تعالى. الألوسي: ٤/١٠٧.\nفي الآية رد على بعض الفرق الضالة بشأن الصحابة، وضح ذلك\nفَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ\nالتوكل هو الاعتماد على الله في تحصيل المنافع، أو حفظها بعد حصولها، وفي دفع المضرات ورفعها بعد وقوعها، وهو من أعلى المقامات لوجهين: أحدهما قوله: ﴿إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَوَكِّلِينَ﴾، والآخر: الضمان الذي في قوله: ﴿وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓ﴾. ابن جزي: ١/١٦٤.\nلمَ كان التوكل على الله من أعلى المقامات؟\nإِن يَنصُرۡكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمۡۖ وَإِن يَخۡذُلۡكُمۡ فَمَن ذَا ٱلَّذِي يَنصُرُكُم مِّنۢ بَعۡدِهِۦۗ\n﴿وَإِن يَخۡذُلۡكُمۡ﴾ ويكلكم إلى أنفسكم ﴿فَمَن ذَا ٱلَّذِي يَنصُرُكُم مِّنۢ بَعۡدِهِۦۗ﴾ فلا بد أن تنخذلوا؛ ولو أعانكم جميع الخلق. وفي ضمن ذلك الأمر بالاستنصار بالله، والاعتماد عليه، والبراءة من الحول والقوة. السعدي: ١٥٤.\nمساعدة الأقوياء لك هل تغني عن الاعتماد والتوكل على الله سبحانه؟\nلَقَدۡ مَنَّ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِينَ إِذۡ بَعَثَ فِيهِمۡ رَسُولٗا مِّنۡ أَنفُسِهِمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ\nتقديم (التلاوة)؛ لأنها من باب التمهيد، ثم (التزكية)؛ لأنها بعده؛ وهي أول أمر يحصل منه صفة يتلبس بها المؤمنون، وهي من قبيل التخلية المقدمة على التحلية؛ لأن درء المفاسد أولى من جلب المصالح. ثم (التعليم)؛ لأنه إنَّما يحتاج إليه بعد الإيمان. الألوسي: ٤/١١٤.\nما الحكمة في ترتيب التلاوة ثم التزكية ثم التعليم؟\nأَوَلَمَّآ أَصَٰبَتۡكُم مُّصِيبَةٞ قَدۡ أَصَبۡتُم مِّثۡلَيۡهَا قُلۡتُمۡ أَنَّىٰ هَٰذَاۖ قُلۡ هُوَ مِنۡ عِندِ أَنفُسِكُمۡۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ١٦٥\nوأخبر أن ما يحصل لهم من مصيبة انتصار العدو وغيرها إنَّما هو بذنوبهم، فقال تعالى في يوم أحد: ﴿أَوَلَمَّآ أَصَٰبَتۡكُم مُّصِيبَةٞ قَدۡ أَصَبۡتُم مِّثۡلَيۡهَا قُلۡتُمۡ أَنَّىٰ هَٰذَاۖ قُلۡ هُوَ مِنۡ عِندِ أَنفُسِكُمۡ﴾. ابن تيمية: ٢/١٦٧.\nما سبب المصائب على الفرد والمجتمع؟"],[72,"§آل عمران\nwords\nالقَرحُالجِرَاحُ، وَالأَلَمُ.\nحَسبُنَاكَافِينَا.\ndeeds\nإذا قرأت أو سمعت في نشرات الأخبار عن مصيبة حلت بمسلمين فقل: \"لا حول ولا قوة إلا بالله\".\nاقرأ كتابًا، أو استمع إلى محاضرة عن فضل الشهادة في سبيل الله.\nحدد ثلاثًا من الشبهات التي تثار على الدعاة أو المجاهدين، ورُدّ عليها من خلال آيات القرآن.\nguid\nتيقن أن كل الأحداث التي تحصل في العالم سبق بها علم الله تعالى، ولا تحدث إلا بإذنه، وأن لها حكمًا عظيمة.\nاحذر المثبطين عن الخير، المقبلين على الدنيا، الراغبين في مصالحهم الخاصة.\nلا خوف ينال المؤمن الصالح إذا مات، ولا حزن يصيبه.\nrefl\nوَمَآ أَصَٰبَكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ فَبِإِذۡنِ ٱللَّهِ\nأخبر أن ما أصابهم يوم التقى الجمعان -جمع المسلمين وجمع المشركين في أحد- من القتل والهزيمة أنه بإذنه وقضائه وقدره، لا مرد له، ولا بد من وقوعه، والأمر القدري إذا نفذ لم يبق إلا التسليم له، وأنه قدَّره لحكم عظيمة، وفوائد جسيمة، وأنه ليتبين بذلك المؤمن من المنافق. السعدي: ١٥٦.\nاستفاد المسلمون فائدة من الهزيمة في أُحد، فما هي؟\nٱلَّذِينَ قَالُواْ لِإِخۡوَٰنِهِمۡ وَقَعَدُواْ لَوۡ أَطَاعُونَا مَا قُتِلُواْۗ قُلۡ فَٱدۡرَءُواْ عَنۡ أَنفُسِكُمُ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ ١٦٨\n﴿لَوۡ أَطَاعُونَا﴾ يريد في ألا يخرجوا إلى قريش. وقوله: (وقعدوا) أي: قالوا هذا القول وقعدوا بأنفسهم عن الجهاد؛ فرد الله عليهم بقوله: (قل فادرؤوا) أي: قل لهم يا محمد: إن صدقتم فادفعوا الموت عن أنفسكم. والدرء: الدفع؛ بيّن بهذا أن الحذر لا ينفع من القدر، وأن المقتول يقتل بأجله، وما علم الله وأخبر به كائن لا محالة. القرطبي: ٥/٤٠٥.\nهل للجهاد أثر في توقيت وفاة الإنسان؟\nوَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ ١٦٩\n﴿بَلۡ أَحۡيَآءٌ﴾ إعلام بأن حال الشهداء حال الأحياء من التمتع بأرزاق الجنة، بخلاف سائر الأموات من المؤمنين؛ فإنهم لا يتمتعون بالأرزاق حتى يدخلوا الجنة يوم القيامة. ابن جزي: ١/١٦٦.\nما وجه كون الشهداء أحياء بعد أن قُتِلوا؟\nوَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ ١٦٩\nولفظ: ﴿عِندَ رَبِّهِمۡ﴾ يقتضي علو درجتهم، وقربهم من ربهم، (يرزقون) من أنواع النعيم الذي لا يعلم وصفه إلا من أنعم به عليهم، ومع هذا (فرحين بما آتاهم الله من فضله) أي: مغتبطين بذلك، قد قرت به عيونهم، وفرحت به نفوسهم؛ وذلك لحسنه، وكثرته، وعظمته، وكمال اللذة في الوصول إليه، وعدم المنغص؛ فجمع الله لهم بين نعيم البدن بالرزق ونعيم القلب والروح بالفرح بما آتاهم من فضله؛ فتم لهم النعيم والسرور. السعدي: ١٥٦.\nيجمع الله للشهيد بين نعيم البدن ونعيم القلب والروح، وضح ذلك.\nفَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ وَيَسۡتَبۡشِرُونَ بِٱلَّذِينَ لَمۡ يَلۡحَقُواْ بِهِم مِّنۡ خَلۡفِهِمۡ أَلَّا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ١٧٠\nلم يفت منهم إلا حياة الكدر التي لا مطمع لأحد في بقائها -وإن طال المدى- وبقيت لهم حياة الصفاء؛ التي لا انفكاك لها، ولا آخر لنعيمها، فلا فتنة تنالهم، ولا حزن يعتريهم، ولا دهش يلم بهم في وقت الحشر، ولا غيره. البقاعي: ٢/١٨٠.\nما حال الذين يقتلون في سبيل الله؟\nوَيَسۡتَبۡشِرُونَ بِٱلَّذِينَ لَمۡ يَلۡحَقُواْ بِهِم مِّنۡ خَلۡفِهِمۡ أَلَّا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ١٧٠\nمن إخوانهم الذين تركوهم أحياء في الدنيا على مناهج الإيمان والجهاد؛ لعلمهم أنهم إذا استشهدوا ولحقوا بهم، ونالوا من الكرامة ما نالوا؛ فهم لذلك مستبشرون. البغوي: ١/٤٤٨.\nلماذا يستبشر الشهداء لحال إخوانهم في الدنيا؟\nٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ ١٧٣\n﴿حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ﴾ كلمة يدفع بها ما يخاف ويكره، وهي التي قالها إبراهيم -عليه السلام- حين أُلقي في النار، ومعنى ﴿حَسۡبُنَا ٱللَّهُ﴾: كافينا وحده؛ فلا نخاف غيره، ومعنى ﴿وَنِعۡمَ ٱلۡوَكِيلُ﴾: ثناء على الله، وأنه خير من يتوكل العبد عليه، ويلجأ إليه. (فانقلبوا) أي: رجعوا بنعمة السلامة، وفضل الأجر. ابن جزي: ١/١٦٧.\nما معنى قول ﴿حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ﴾؟"],[73,"§آل عمران\nwords\nفَانقَلَبُوارَجَعُوا.\nنُملِينُمهِلُهُم بِطُولِ البَقَاءِ.\nيَجتَبِييَصطَفِي.\ndeeds\nتأمل ثلاثة من أنواع الرفاهية والنعيم التي تعيشها الدول الكافرة لتعرف كيفية استدراج الله لهم.\nتأمل ثلاثة من طرق الشيطان في الغواية والإضلال.\nساعد اليوم أحدًا بمالك، أو جاهك، أو بما تقدر عليه، وتذكر أن الله تعالى سيبارك لك في فعلك.\nguid\nعلى قدر إيمان العبد يكون خوفه من الله.\nاحذر من الإمهال؛ ففيه زيادة آثام، وبادر بالتوبة من كل ذنب.\nمن حِكَم التكليف: إظهار المؤمن الصادق من المؤمن الكاذب.\nrefl\nفَٱنقَلَبُواْ بِنِعۡمَةٖ مِّنَ ٱللَّهِ وَفَضۡلٖ لَّمۡ يَمۡسَسۡهُمۡ سُوٓءٞ وَٱتَّبَعُواْ رِضۡوَٰنَ ٱللَّهِۗ وَٱللَّهُ ذُو فَضۡلٍ عَظِيمٍ ١٧٤\nلمَّا فوضوا أمورهم إليه، واعتمدوا بقلوبهم عليه؛ أعطاهم من الجزاء أربعة معان: النعمة، والفضل، وصرف السوء، واتباع الرضا؛ فرَضَّاهم عنه، ورضي عنهم. القرطبي: ١٦/٤١٧.\nما المنح الأربع التي نالها أهل الإيمان لمَّا فوضوا أمرهم إلى ربهم سبحانه؟\nإِنَّمَا ذَٰلِكُمُ ٱلشَّيۡطَٰنُ يُخَوِّفُ أَوۡلِيَآءَهُۥ فَلَا تَخَافُوهُمۡ وَخَافُونِ إِن كُنتُم مُّؤۡمِنِينَ ١٧٥\nفالخائف من الله تعالى هو أن يخاف أن يعاقبه: إما في الدنيا، وإما في الآخرة، ولهذا قيل: ليس الخائف الذي يبكي ويمسح عينيه، بل الخائف الذي يترك ما يخاف أن يُعذب عليه. القرطبي: ٥/٤٢٨.\nمن الخائف من عذاب الله تعالى حقيقة؟\nإِنَّمَا ذَٰلِكُمُ ٱلشَّيۡطَٰنُ يُخَوِّفُ أَوۡلِيَآءَهُۥ فَلَا تَخَافُوهُمۡ وَخَافُونِ إِن كُنتُم مُّؤۡمِنِينَ ١٧٥\nأولياء الرحمن إذا ثبتوا لأجل الله أنجز الله لهم ما وعدهم من النصرة على أولياء الشيطان، ومن خاف من تخويفه وعمل بموجب خوفه ففيه ولاية له. البقاعي: ٢/١٨٥\nبما يوصف من يخاف من الشيطان ويعمل بموجب خوفه؟\nوَلَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِۚ إِنَّهُمۡ لَن يَضُرُّواْ ٱللَّهَ شَيۡٔاًۗ يُرِيدُ ٱللَّهُ أَلَّا يَجۡعَلَ لَهُمۡ حَظّٗا فِي ٱلۡأٓخِرَةِۖ وَلَهُمۡ عَذَابٌ عَظِيمٌ ١٧٦\n(إنهم لن يضروا الله شيئًا) تعليق نفي الضرر به تعالى تشريف للمؤمنين، وإيذان بأن مضارتهم بمنزلة مضارته -سبحانه وتعالى-. الألوسي: ٤/١٣٣.\nلماذا علق الله تعالى نفي الضرر به؟\nمَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلۡمُؤۡمِنِينَ عَلَىٰ مَآ أَنتُمۡ عَلَيۡهِ حَتَّىٰ يَمِيزَ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِۗ وَمَا كَانَ ٱللَّهُ لِيُطۡلِعَكُمۡ عَلَى ٱلۡغَيۡبِ\nما كان الله ليدع المؤمنين مختلطين بالمنافقين، ولكنه ميز هؤلاء من هؤلاء بما ظهر في غزوة أُحُد من الأقوال والأفعال التي تدل على الإيمان، أو على النفاق، ﴿وَمَا كَانَ ٱللَّهُ لِيُطۡلِعَكُمۡ عَلَى ٱلۡغَيۡبِ﴾ أي: ما كان الله ليطلعكم على ما في القلوب من الإيمان والنفاق. ابن جزي: ١/١٦٨.\nتبيّنت حكمة عظيمة للمسلمين من خلال الهزيمة في أُحُد، فما هي؟\nمَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلۡمُؤۡمِنِينَ عَلَىٰ مَآ أَنتُمۡ عَلَيۡهِ حَتَّىٰ يَمِيزَ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِۗ\n﴿حَتَّىٰ يَمِيزَ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِۗ﴾ بأن يفضح المبطل -وإن طال ستره- بتكاليف شاقة، وأحوال شديدة، لا يصبر عليها إلا المخلص من العباد، المخلصون في الاعتقاد. البقاعي: ٢/١٨٧.\nكيف يميز الله الخبيث من الطيب؟\nوَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ ١٨٠\nأخبر تعالى ببقائه ودوام ملكه، وأنه في الأبد كهو في الأزل؛ غني عن العالمين، فيرث الأرض بعد فناء خلقه وزوال أملاكهم، فتبقى الأملاك والأموال لا مدعى فيها. القرطبي: ٥/٤٤٢.\nبيّن عظمة الخالق تعالى وحقارة الخلق."],[74,"§آل عمران\nwords\nبِقُربَانٍبِصَدَقَةٍ يُتَقَرَّبُ بِهَا إِلَى اللهِ.\nوَالزُّبُرِالكُتُبِ الكَاشِفَةِ لِلظُّلُمَاتِ.\nزُحزِحَأُبعِدَ.\ndeeds\nألزِم نفسكَ هذا اليوم ألا تقول شيئًا إلا إذا كان مرضيًا لله تعالى، متذكرًا الآية.\nاستمع اليوم إلى محاضرة، أو اقرأ قصة عن الموت، أو اذهب لزيارة القبور، واجعله عملًا دوريًا لك.\nاستعرض في ذهنك حياة أحد معارفك ممن اشتد ابتلاؤه، واستخرج ثلاث فوائد من ذلك.\nguid\nما أعظم حلم الله تعالى وصبره على أذى عباده.\nأسعد الناس من أتته منيته وقد زحزحه الله تعالى عن النار، وأدخله الجنة.\nإذا قيل: الدنيا؛ فإنها تعني: مركبك، ومسكنك، وملبسك، ومأكلك، ومحاولتك التميز عن غيرك في ذلك. إنَّما هي بداية الغفلة، ثم الغرور والهلاك.\nrefl\nسَنَكۡتُبُ مَا قَالُواْ وَقَتۡلَهُمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَنَقُولُ ذُوقُواْ عَذَابَ ٱلۡحَرِيقِ ١٨١\nسلَّاه ربه في تكذيب المكذبين للرسل من قبله ليتأسى بهم؛ فموت النبي الكريم وقتله ممكن كما كان من قبله من إخوانه من الرسل. وختم بالإخبار بأنه وقع قتل كثير من الرسل، فكان ذلك محققًا؛ لأنه لا يصان من الموت خاص ولا عام. البقاعي: ٢/١٩٢.\nما الحكمة من الإخبار بقتل الأنبياء؟\nسَنَكۡتُبُ مَا قَالُواْ وَقَتۡلَهُمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَنَقُولُ ذُوقُواْ عَذَابَ ٱلۡحَرِيقِ ١٨١\nكانوا راضين بما فعل أوائلهم من قتل من قتلوا من الأنبياء، وكانوا منهم، وعلى منهاجهم من استحلال ذلك، واستجازته؛ فأضاف -جل ثناؤه- فعل ما فعله من كانوا على منهاجه وطريقته إلى جميعهم؛ إذ كانوا أهل ملة واحدة ونحلة واحدة، وبالرضى من جميعهم. الطبري: ٧/٤٤٦.\nما وجه إضافة قتل الأنبياء -عليهم السلام- إلى اليهود المعاصرين؛ مع أن الفاعلين هم أسلافهم؟\nوَقَتۡلَهُمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ\n﴿بِغَيۡرِ حَقٍّ﴾ هذا القيد يراد به: أنهم تجرأوا على قتلهم مع علمهم بشناعته، لا جهلًا وضلالًا، بل تمردًا وعنادًا. السعدي: ١٥٩.\nلماذا وصف الله قتل اليهود للأنبياء بأنه بغير حق؟\nكُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَإِنَّمَا تُوَفَّوۡنَ أُجُورَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۖ فَمَن زُحۡزِحَ عَنِ ٱلنَّارِ وَأُدۡخِلَ ٱلۡجَنَّةَ فَقَدۡ فَازَۗ وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا مَتَٰعُ ٱلۡغُرُورِ ١٨٥\nيندم المغرور بالمتاع الذي غر به، فالسعيد من سعى في أن يكون موته في رضى مولاه. البقاعي: ٢/١٩٣.\nما علامة الخاتمة السعيدة؟\nكُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۗ وَإِنَّمَا تُوَفَّوۡنَ أُجُورَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۖ فَمَن زُحۡزِحَ عَنِ ٱلنَّارِ وَأُدۡخِلَ ٱلۡجَنَّةَ فَقَدۡ فَازَۗ\nلمَّا سلَّاه -سبحانه وتعالى- بالرسل الذين لازموا الصبر والاجتهاد في الطاعة حتى ماتوا وأممهم، وتركوا ما كان بأيديهم عاجزين عن المدافعة، ولم يبق إلا ملكه -سبحانه وتعالى-، وأن الفريقين ينتظرون الجزاء؛ فالرسل لتمام الفوز، والكفار لتمام الهلاك، أخبر أن كل نفس كذلك؛ ليجتهد الطائع، ويقتصر العاصي. البقاعي: ٢/١٩٢.\nما مقياس المؤمنين، وما مقياس المنافقين للفوز في الدنيا؟\nلَتُبۡلَوُنَّ فِيٓ أَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذٗى كَثِيرٗاۚ\nأخبرهم ليوطنوا أنفسهم على احتماله، ويستعدوا للقائه، ويقابلوه بحسن الصبر والثبات؛ فإن هجوم البلاء مما يزيد في اللأواء، والاستعداد للكرب مما يهون الخطب. الألوسي: ٤/١٤٧.\nلماذا يخبر الله -سبحانه وتعالى- الدعاة والمؤمنين بأنهم سيبتلون؟\nوَإِن تَصۡبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ ١٨٦\nفإن (التقوى) تتضمن: فعل المأمور وترك المحظور. و(الصبر) يتضمن: الصبر على المقدور. ابن تيمية: ٢/١٨٥.\nما الذي تتضمنه التقوى والصبر في الآية الكريمة؟"],[75,"§آل عمران\nwords\nوَكَفِّراستُر.\ndeeds\nابحث اليوم عن جاهل بأحكام الوضوء والصلاة، أو قصار السور، وعلّمه إياها.\nاحرص اليوم على أذكار الصباح والمساء، ودرب نفسك على أن تذكر الله على كل الأحوال: قائمًا وقاعدًا وعلى جنبك.\nانظر هذه الليلة إلى السماء، وإلى طلوع الشمس وغروبها، واستخرج من كل واحدة فائدة على قدرته سبحانه.\nguid\nيهلك المجتمع إذا كتم العلماء الحق إرضاء للناس، أو ليحوزوا على مكاسب دنيوية: مالًا، أو جاهًا، أو سلطانًا.\nحق المجتمع على العالِم أن ينشر العلم الذي أخذه ولا يكتمه.\nاحذر أن يتسلل لقلبك حب المدح والثناء، وأعظم منه أن تحب المدح بما لم تفعل.\nrefl\nوَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكۡتُمُونَهُۥ\nقال الحسن وقتادة: \"هي في كل من أوتي علم شيء من الكتاب؛ فمن علم شيئًا فليُعَلِّمه، وإياكم وكتمان العلم؛ فإنه هلكة\". وقال محمد بن كعب: \"لا يحل لعالم أن يسكت على علمه، ولا للجاهل أن يسكت على جهله؛ قال الله تعالى: ﴿وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ﴾ الآية، وقال: ﴿فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ﴾ [النحل: ٤٣]\"، وقال أبو هريرة: \"لولا ما أخذ الله على أهل الكتاب ما حدثتكم بشيء\"، ثم تلا هذه الآية: ﴿وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ﴾. القرطبي:٥/٤٥٨.\nقال تعالى: ﴿أُوتُواْ ٱلۡكِتَٰبَ﴾ ولم يقل: أخذوا الكتاب، ما دلالة هذه اللفظة وتبعاتها؟\nٱلَّذِينَ يَذۡكُرُونَ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِهِمۡ وَيَتَفَكَّرُونَ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ\nقدَّم الذكر على الدّوام على التفكر للتنبيه على أن العقل لا يفي بالهداية ما لم يتنوّر بنور ذكر الله تعالى وهدايته؛ فلا بد للمتفكر من الرجوع إلى الله تعالى. الألوسي: ٤/١٥٩.\nلماذا قدم الذكر على التفكر؟\nٱلَّذِينَ يَذۡكُرُونَ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِهِمۡ\nأراد به المداومة على الذكر في عموم الأحوال. البغوي: ١/٤٦٥.\nما المراد بوصف الله تعالى لأولي الألباب بالذكر في هذه الأحوال الثلاثة؟\nوَيَتَفَكَّرُونَ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبَّنَا مَا خَلَقۡتَ هَٰذَا بَٰطِلٗا سُبۡحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ ١٩١\nقيل لأم الدرداء: ما كان شأن أبي الدرداء؟ قالت: كان أكثر شأنه التفكر، قيل له: أترى التفكر عملًا من الأعمال؟ قال: نعم، هو اليقين. ابن عاشور: ٤/١٩٦.\nبينت الآية وسيلة من وسائل الوصول إلى اليقين، فما هي؟\nوَيَتَفَكَّرُونَ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبَّنَا مَا خَلَقۡتَ هَٰذَا بَٰطِلٗا سُبۡحَٰنَكَ\nقال ابن عون: \"الفكرة تُذهِب الغفلة، وتُحدِث للقلب الخشية، كما يُحدِث الماءُ للزرع النباتَ، وما جُليت القلوبُ بمثل الأحزان، ولا استنارت بمثل الفكرة\". البغوي: ١/٤٦٥.\nما أهمية التفكر وفائدته؟\nرَبَّنَآ إِنَّكَ مَن تُدۡخِلِ ٱلنَّارَ فَقَدۡ أَخۡزَيۡتَهُۥۖ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٖ ١٩٢\nقال أبو الدرداء: \"يرحم الله المؤمنين؛ ما زالوا يقولون: (ربنا) (ربنا)؛ حتى استجيب لهم\". ابن عطية: ١/٥٥٦.\nما سبب الاستجابة للمؤمنين الذي أشار إليه أبوالدرداء رضي الله عنه؟\nرَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ ١٩٣\nقولهم ﴿مَعَ ٱلۡأَبۡرَارِ﴾ دون \"أبرارًا\" أي: لسنا بأبرار؛ فاسلكنا معهم، واجعلنا من أتباعهم؛ وفي ذلك هضم للنفس، وحسن أدب. الألوسي: ٤/١٦٥.\nلماذا لم يقل: \"توفنا أبرارًا\" بدل ﴿مَعَ ٱلۡأَبۡرَارِ﴾؟"],[76,"§آل عمران\nwords\nتَقَلُّبُسَعَةُ عَيشٍ، وَكَثرَةُ تَنَقُّلٍ وَتَصَرُّفٍ.\nالمِهَادُالفِرَاشُ.\nنُزُلًاضِيَافَةً، وَمَنزِلًا.\nوَرَابِطُواأَقِيمُوا عَلَى جِهَادِ عَدُوِّكُم.\ndeeds\nادع اليوم بالأدعية التي جاءت في الآيات؛ رجاء أن يستجاب دعاؤك.\nاحرص اليوم أكثر على اجتناب النظر المحرم تقوى لله تعالى، وصبرًا عن المعصية.\nاختر كلمات جميلة، أو قصة في فضل الصبر، وعظيم أجره، وأرسلها في رسالة.\nguid\nلا يغرنك استعلاء الكافرين، وتمكنهم من هذه الحياة الدنيا؛ فإن وراء هذا حِكَمًا أرادها الله -سبحانه وتعالى-.\nلا يكن همك من وراء حفظ القرآن وتدبره والعمل به الحصول على المكاسب الدنيوية.\nأهمية الصبر، والمصابرة، والمرابطة، والتقوى؛ للحصول على الفلاح الذي هو النصر في الدنيا، والفوز في الآخرة.\nrefl\nفَٱلَّذِينَ هَاجَرُواْ وَأُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأُوذُواْ فِي سَبِيلِي وَقَٰتَلُواْ وَقُتِلُواْ لَأُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَلَأُدۡخِلَنَّهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ\n﴿فَٱلَّذِينَ هَاجَرُواْ﴾ أي: تركوا دار الشرك، وأتوا إلى دار الإيمان، وفارقوا الأحباب والخلان والإخوان والجيران. ﴿وَأُخۡرِجُواْ مِن دِيَٰرِهِمۡ﴾ أي: ضايقهم المشركون بالأذى حتى ألجأوهم إلى الخروج من بين أظهرهم؛ ولهذا قال: ﴿وَأُوذُواْ فِي سَبِيلِي﴾ أي: إنَّما كان ذنبهم إلى الناس أنهم آمنوا بالله وحده؛ ﴿وَمَا نَقَمُواْ مِنۡهُمۡ إِلَّآ أَن يُؤۡمِنُواْ بِٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ﴾ [البروج: ٨]. وقوله: ﴿وَقَٰتَلُواْ وَقُتِلُواْ﴾: وهذا أعلى المقامات؛ أن يقاتل في سبيل الله. ابن كثير: ١/٤١٨.\nما جزاء من هاجر، أو أخرج من دياره، أو أُوذي، أو قُتل في سبيل الله؟\nلَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُواْ فِي ٱلۡبِلَٰدِ ١٩٦\nدليل على أن الكفار غير منعم عليهم في الدنيا؛ لأن حقيقة النعمة الخلوص من شوائب الضرر العاجلة والآجلة، ونِعَم الكفار مشوبة بالآلام والعقوبات، فصار كمن قدم بين يدي غيره حلاوة من عسل فيها السم، فهو وإن استلذ آكله لا يقال أنعم عليه؛ لأن فيه هلاك روحه. القرطبي: ٥/٤٨١.\nهل يُنَعَّم الكفار في الدنيا؟\nلَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُواْ فِي ٱلۡبِلَٰدِ ١٩٦\nالمغتر فارح بالشيء الذي يغتر به، فالكفار مغترون بتقلبهم، والمؤمنون مهتمون به، لكنه ربما يقع في نفس مؤمن أن هذا الإملاء للكفار إنَّما هو لخير لهم، فيجيء هذا جنوحًا إلى حالهم ونوعًا من الاغترار؛ فلذلك حسنت ﴿لَا يَغُرَّنَّكَ﴾... ما من مؤمن ولا كافر إلا والموت خير له، أما الكافر فلئلَّا يزداد إثمًا، وأمَّا المؤمن فلأن ما عند الله خير للأبرار. ابن عطية: ١/٥٥٨.\nعلل سبب اختيار لفظ الغرور هنا.\nنُزُلٗا مِّنۡ عِندِ ٱللَّهِۗ وَمَا عِندَ ٱللَّهِ خَيۡرٞ لِّلۡأَبۡرَارِ ١٩٨\n(للأبرار): جمع بارّ وبَرّ، ومعناه: العاملون بالبر، وهي غاية التقوى والعمل الصالح؛ قال بعضهم: الأبرار هم الذين لا يؤذون أحدًا. ابن جزي: ١/١٧٠.\nمن المقصود بالأبرار؟\nوَإِنَّ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ لَمَن يُؤۡمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡكُمۡ وَمَآ أُنزِلَ إِلَيۡهِمۡ خَٰشِعِينَ لِلَّهِ\nلما كان إيمانهم عامًّا حقيقيًّا؛ صار نافعًا؛ فأحدث لهم خشية الله... ومن تمام خشيتهم لله أنهم ﴿لَا يَشۡتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًا قَلِيلًاۚ﴾؛ فلا يقدمون الدنيا على الدين كما فعل أهل الانحراف الذين يكتمون ما أنزل الله، ويشترون به ثمنًا قليلًا، وأمَّا هؤلاء فعرفوا الأمر على الحقيقة، وعلموا أن من أعظم الخسران الرضا بالدون عن الدين. السعدي: ١٦٢.\nما علامة الإيمان الحقيقي؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱصۡبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ ٢٠٠\nختم تعالى السورة بما تضمنته هذه الآية العاشرة من الوصاة التي جمعت الظهور في الدنيا على الأعداء والفوز بنعيم الآخرة، فحض على الصبر على الطاعات، وعن الشهوات، والصبر: الحبس. القرطبي: ٥/٤٨٥.\nذكرت الآية عدة شروط للظهور على الأعداء، والفوز بالآخرة، فما هي؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱصۡبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ ٢٠٠\nهذه الآية معلمة بشرط استجابة الدعاء بالنصرة على الكافرين، داعية إلى تذكير أولي الألباب بالمراقبة للواحد الحي القيوم. البقاعي: ٢/٢٠٣.\nما شرط استجابة الله تعالى للمؤمنين بالنصر؟"],[77,"§النساء\nwords\nحُوبًاإِثمًا.\nتُقسِطُواتَعدِلُوا.\nأَدنَى أَلاَّ تَعُولُواأَقرَبُ إِلَى عَدَمِ الجَورِ.\nنِحلَةًفَرِيضَةً عَن طِيبِ نَفسٍ.\nآنَستُمعَلِمتُم.\nوَبِدَارًامُبَادَرَةً.\nحَسِيبًامُحَاسِبًا، وَشَاهِدًا.\ndeeds\nابدأ اليوم بوضع جدول لزيارة أرحامك، والاتصال على البعيد منهم.\nساعد أيتامًا على حفظ مالهم.\nضع ميزانيةً شخصيةً توازن فيها بين متطلبات الدنيا والآخرة.\nguid\nمن غلب على ظنه عدم القدرة على العدل بين الزوجات فلا يُعَدِّد.\nتعامل مع مال اليتيم كما تحب أن يتعامل الناس مع مال ورثتك بعد موتك.\nالأمر بوجود شاهد عند دفع المال لليتيم تبرئةً لذمة القائم على المال، وحفظًا لسمعته.\nrefl\nوَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَيۡكُمۡ رَقِيبٗا ١\nمقام المراقبة -وهو مقام شريف- أصله: علمٌ وحال؛ أما العلم فهو: معرفة العبد أن الله مطلع عليه، ناظر إليه، يرى جميع أعماله، ويسمع جميع أقواله، ويعلم كل ما يخطر على باله. وأمَّا الحال فهي: ملازمة هذا العلم للقلب بحيث يغلب عليه، ولا يغفل عنه. ولا يكفي العلم دون هذه الحال. ابن جزي: ١/١٧٢.\nما أصل المراقبة؟\nوَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَيۡكُمۡ رَقِيبٗا ١\nوأعيد فعل (اتقوا)؛ لأن هذه التقوى مأمور بها المسلمون خاصة؛ فإنهم قد بقيت فيهم بقية من عوائد الجاهلية لا يشعرون بها؛ وهي التساهل في حقوق الأرحام والأيتام. ابن عاشور: ٤/٢١٧.\nلماذا كرر الأمر بالتقوى مرتين في هذه الآية؟\nوَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَيۡكُمۡ رَقِيبٗا ١\nالموجب الداعي لتقواه تساؤلكم به، وتعظيمكم، حتى إنكم إذا أردتم قضاء حاجاتكم ومآربكم توسلتم لها بالسؤال بالله، فيقول من يريد ذلك لغيره: أسألك بالله أن تفعل الأمر الفلاني؛ لعلمه بما قام في قلبه من تعظيم الله الداعي أن لا يرد من سأله بالله، فكما عظمتموه بذلك فلتعظموه بعبادته وتقواه. السعدي: ١٦٣.\nنعظم الله سبحانه في أمور، ونغفل عن تعظيمه في أمور أخرى، وضح ذلك.\nوَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ وَلَا تَتَبَدَّلُواْ ٱلۡخَبِيثَ بِٱلطَّيِّبِۖ\nقد تقدم في السورة الماضية ذكر قصة أحد التي انكشفت عن أيتام، ثم ذكر في قوله تعالى: ﴿كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِ﴾ أن الموت مشرع [لا بد] لكل نفس من وروده؛ علم أنه [لا بد] من وجود الأيتام في كل وقت، فدعا إلى العفة والعدل فيهم؛ لأنهم بعد الأرحام أولى من يُتّقى الله فيه، ويُخشى مراقبته بسببه، فقال: ﴿وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ﴾. البقاعي: ٢/٢٠٧.\nما مناسبة ذكر الأيتام في سورة النساء بعد ذكر الموت وقصة أحد في آخر آل عمران؟\nفَٱنكِحُواْ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۖ\nفاختاروا على نظركم، ومن أحسن ما يختار من ذلك صفة الدين؛ كما قال النبي -صلى الله عليه وسلم-: «تنكح المرأة لأربع: لمالها ولجمالها ولحسبها ولدينها؛ فاظفر بذات الدين تربت يمينك». وفي هذه الآية أنه ينبغي للإنسان أن يختار قبل النكاح، بل وقد أباح له الشارع النظر إلى من يريد تزوجها؛ ليكون على بصيرة من أمره. السعدي: ١٦٤.\nفي قوله تعالى: ﴿مَا طَابَ لَكُم﴾ إشارة إلى أهمية اختيار الزوجة، بين ذلك.\nفَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُواْ فَوَٰحِدَةً أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۚ\nوفي هذا: أن تعرُّض العبد للأمر الذي يخاف منه الجور والظلم وعدم القيام بالواجب -ولو كان مباحًا- أنه لا ينبغي له أن يتعرض له، بل يلزم السعة والعافية؛ فإن العافية خير ما أُعطي العبد. السعدي: ١٦٤.\nإذا غلب على الظن حصول الظلم؛ فمن الحكمة الابتعاد عن أسبابه، وضح ذلك من الآية.\nوَلَا تُؤۡتُواْ ٱلسُّفَهَآءَ أَمۡوَٰلَكُمُ ٱلَّتِي جَعَلَ ٱللَّهُ لَكُمۡ قِيَٰمٗا\nفي الآية إشارة إلى مدح الأموال، وكان السلف يقولون: \"المال سلاح المؤمن، ولأن أترك مالًا يحاسبني الله تعالى عليه خير من أن أحتاج إلى الناس\"... وكانوا يقولون: \"اتّجروا واكتسبوا؛ فإنكم في زمان إذا احتاج أحدكم كان أول ما يأكل دينه\". الألوسي: ٤/٢٠٢.\nإلى ماذا يشير قوله: ﴿أَمۡوَٰلَكُمُ ٱلَّتِي جَعَلَ ٱللَّهُ لَكُمۡ قِيَٰمًا﴾ ؟"],[78,"§النساء\nwords\nوَسَيَصلَونَسَيُدخَلُونَ.\nإِخوَةٌاثنَانِ فَأَكثَرُ.\ndeeds\nأرسل رسالة تذكر فيها الآباء والأمهات بأهمية العدل بين الأولاد.\nبادر اليوم بكتابة وصيتك.\nضع اليوم جدولًا زمنيًا لقضاء ديونك -إن وجدت- قبل أن تتضاعف، واستعن بالله على ذلك.\nguid\nحق المرأة في الإرث ثابت بالكتاب والسنة.\nحرمة أكل مال اليتامى ظلمًا، والوعيد الشديد فيه.\nعلى من يخاف على أطفاله بعد موته أن يحسن إلى أطفال غيره؛ فإن الله تعالى يكافئه بالإحسان.\nrefl\nلِّلرِّجَالِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ مِمَّا قَلَّ مِنْهُ أَوْ كَثُرَ نَصِيبًأ مَّفۡرُوضٗا ٧\nكان العرب في الجاهلية من جبروتهم وقسوتهم لا يورثون الضعفاء؛ كالنساء والصبيان، ويجعلون الميراث للرجال الأقوياء؛ لأنهم بزعمهم أهل الحرب والقتل، والنهب والسلب، فأراد الرب الرحيم الحكيم أن يشرع لعباده شرعًا يستوي فيه رجالهم ونساؤهم، وأقوياؤهم وضعفاؤهم، وقدَّم بين يدي ذلك أمرًا مجملًا لتتوطن على ذلك النفوس، فيأتي التفصيل بعد الإجمال، قد تشوفت له النفوس، وزالت الوحشة التي منشؤها العادات القبيحة. السعدي: ١٦٥.\nبيّن الأسلوب القرآني الحكيم في تغيير العادات القبيحة المتأصلة في النفوس.\nوَإِذَا حَضَرَ ٱلۡقِسۡمَةَ أُوْلُواْ ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينُ فَٱرۡزُقُوهُم مِّنۡهُ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا ٨\nويؤخذ من المعنى: أن كل مَن له تطلع وتشوف إلى ما حضر بين يدي الإنسان؛ ينبغي له أن يعطيه منه ما تيسر. السعدي: ١٦٥.\nإشراك الحاضرين المتطلعة نفوسهم فيه خير للآخذ والمعطي، وضح ذلك.\nوَإِذَا حَضَرَ ٱلۡقِسۡمَةَ أُوْلُواْ ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينُ فَٱرۡزُقُوهُم مِّنۡهُ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا ٨\nوالأمر بأن يقولوا لهم قولًا معروفًا، أي: قولًا حسنًا -وهو ضد المنكر- تسليةً لبعضهم على ما حُرموا منه من مال الميت. ابن عاشور: ٤/٢٥٢.\nلماذا جاء الأمر بالقول المعروف في هذا الموضع من الآية الكريمة؟\nوَلۡيَخۡشَ ٱلَّذِينَ لَوۡ تَرَكُواْ مِنۡ خَلۡفِهِمۡ ذُرِّيَّةٗ ضِعَٰفًا خَافُواْ عَلَيۡهِمۡ فَلۡيَتَّقُواْ ٱللَّهَ وَلۡيَقُولُواْ قَوۡلٗا سَدِيدًا ٩\nأي: فليعدلوا في أمرهم؛ ليقيِّض الله لهم من يعدل في ذريتهم، وليقولوا قولًا عدلًا قاصدًا صوابًا، وإلا أوشك أن يسلط على ذريتهم من يجور عليهم. البقاعي: ٢/٢١٨.\nالجزاء من جنس العمل، وضح ذلك من الآية.\nيُوصِيكُمُ ٱللَّهُ فِيٓ أَوۡلَٰدِكُمۡۖ\nهذا مما يدل على أن الله تعالى أرحم بعباده من الوالدين؛ حيث أوصى الوالدين مع كمال شفقتهم عليهم. السعدي: ١٦٦.\nكيف تستدل بالآية على أن الله أرحم بعباده من والديهم؟\nمِنۢ بَعۡدِ وَصِيَّةٖ يُوصِي بِهَآ أَوۡ دَيۡنٍۗ\nتقديم الوصية على الدَين ذكرًا مع أن الدَّين مقدَّم عليها حكمًا؛ لإظهار كمال العناية بتنفيذها؛ لكونها مظنة للتفريط في أدائها؛ حيث إنها تؤخذ كالميراث بلا عوض، فكانت تشُقُّ عليهم. الألوسي: ٤/٢٢٧.\nلماذا قدم الوصية على الدَّين مع أن الدَّين مقدم حكمًا؟\nيُوصِيكُمُ ٱللَّهُ فِيٓ أَوۡلَٰدِكُمۡۖ ... إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا ١١\nوضع لكم هذه الأحكام على غاية الإحكام في جلب المنافع لكم ودفع الضر عنكم، ورتبها -سبحانه وتعالى- أحسن ترتيب؛ فقدَّم ما هو بلا واسطة لشدة قربه، وبدأ منه بالنسب لقوته، وبدأ منهم بالولد لمزيد الاعتناء به. البقاعي: ٢/٢٢١.\nما دلالة اسمي الله العليم الحكيم في ختام آيات المواريث؟"],[79,"§النساء\nwords\nوَلَدٌابنٌ، أَو بِنتٌ.\nكَلاَلَةًمَن لَيسَ لَهُ وَلَدٌ، وَلاَ وَالِدٌ.\ndeeds\nبادر بكتابة وصيتك، كما قال -صلى الله عليه وسلم-: «ما حق امرئ مسلم يبيت ليلتين وله شيء يريد أن يوصي به إلا وصيته مكتوبة عند رأسه» [متفق عليه].\nأحكام المواريث إذا طبقت بحق، فإنها تزيد الأرحام أُلفة.\nلو ترك لنا قسمة مواريثنا لاشتدت مشاكلنا؛ تأمل ذلك، ثم احمد الله تعالى على نعمة أحكام المواريث.\nguid\nأحكمت الشريعة انتقال الأموال بين الناس بكل صوره وأشكاله؛ لأثر ذلك على العباد، ولإصلاح دنياهم.\nمن استهان بالعدل بين الورثة أهانه الله يوم القيامة.\nاعلم أن الله تعالى تولى قسمة التركات بنفسه، فلا يحل لأحد أن يغيّر منها شيئًا.\nrefl\nوَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡوَٰجُكُمۡ\nوتأمل هذا المعنى في آية المواريث، وتعليقه سبحانه التوارث فيها بلفظ الزوجة دون المرأة؛ كما في قوله تعالى: ﴿۞وَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡوَٰجُكُمۡ﴾ إيذانًا بأن هذا التوارث إنَّما وقع بالزوجية المقتضية للتشاكل والتناسب، والمؤمن والكافر لا تشاكل بينهما، ولا تناسب، فلا يقع بينهما التوارث. السعدي: ١٦٩.\nفي آية المواريث لماذا عبر بلفظ الزوجة دون لفظ المرأة؟\nمِنۢ بَعۡدِ وَصِيَّةٖ يُوصِي بِهَآ أَوۡ دَيۡنٍۗ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِينَ بِهَآ أَوۡ دَيۡنٖۚ مِّنۢ بَعۡدِ وَصِيَّةٖ تُوصُونَ بِهَآ أَوۡ دَيۡنٖۗ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصَىٰ بِهَآ أَوۡ دَيۡنٍ\nكرر حكم الوصية اهتمامًا بشأنها، وإشارة إلى أن الوصية أمر عظيم ينبغي أن يكون مستحضرًا في الذهن، غير مغفول عنه عند أحد من الناس. البقاعي: ٢/٢٢٢.\nلماذا كرر حكم الوصية؟\nغَيۡرَ مُضَآرّٖۚ وَصِيَّةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَلِيمٞ ١٢\nالإضرار في الوصية من الكبائر، ووجوه المضار كثيرة؛ منها: الوصية لوارث، والوصية بأكثر من الثلث، أو بالثلث فرارًا عن وارث محتاج. ابن جزي: ١/١٧٩.\nعدد بعض أشكال المضارة بالوصية.\nغَيۡرَ مُضَآرّٖۚ وَصِيَّةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَلِيمٞ ١٢\nجعل حقوق المسلمين أولى من حقوق الأقارب الكفار الدنيوية، فإذا مات المسلم انتقل ماله إلى من هو أولى وأحق به، فيكون قوله تعالى: ﴿وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ﴾ [الأنفال:٧٥] إذا اتفقت أديانهم، وأمَّا مع تباينهم؛ فالأخوة الدينية مقدمة على الأخوة النسبية المجردة. السعدي: ١٦٩.\nأيهما أقوى: الأُخوة الدينية، أم أُخوة النسب؟ وضح ذلك من خلال أحكام الميراث.\nيُدۡخِلۡهُ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ يُدۡخِلۡهُ نَارًا خَٰلِدٗا فِيهَا\n﴿خَٰلِدِينَ فِيهَا﴾، ﴿خَٰلِدًا فِيهَا﴾ أفرد هنا وجمع هناك؛ لأن أهل الطاعة أهل الشفاعة، وإذا شفع أحدهم في غيره دخلها معه، وأهل المعاصي لا يشفعون؛ فلا يدخل بهم غيرهم فيبقون فرادى، أو للإيذان بأن الخلود في دار الثواب بصيغة الاجتماع الذي هو أجلب للأنس، والخلود في دار العقاب بصيغة الانفراد الذي هو أشد في استجلاب الوحشة. الألوسي: ٤/٢٣٣.\nلماذا أفرد في الخلود في النار: (خالدًا)، وجمع في الخلود في الجنة: (خالدين)؟\nتِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ١٣ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدۡخِلۡهُ نَارًا خَٰلِدٗا فِيهَا وَلَهُۥ عَذَابٞ مُّهِينٞ ١٤\n﴿وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ﴾ أي: فيها؛ فلم يزد بعض الورثة، ولم ينقص بعضًا بحيلة ووسيلة، بل تركهم على حكم الله وفريضته وقسمته ﴿يُدۡخِلۡهُ جَنَّٰتٍ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ﴾، ﴿وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدۡخِلۡهُ نَارًا خَٰلِدًا فِيهَا وَلَهُۥ عَذَابٌ مُّهِينٌ﴾ أي: لكونه غيَّر ما حكم الله به، وضادَّ الله في حكمه. ابن كثير: ١/٤٣٧.\nالقائم على تقسيم التركة واقع بين وعد ووعيد عظيمين، وضح ذلك من الآية.\nوَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدۡخِلۡهُ نَارًا خَٰلِدٗا فِيهَا\nمن اجتمع فيه معصية وطاعة كان فيه من موجب الثواب والعقاب بحسب ما فيه من الطاعة والمعصية، وقد دلت النصوص المتواترة على أن الموحدين -الذين معهم طاعة التوحيد- غير مخلدين في النار، فما معهم من التوحيد مانع لهم من الخلود فيها. السعدي: ١٦٩.\nبيّن فضل التوحيد."],[80,"§النساء\nwords\nبِجَهَالَةٍبِسَفَهٍ، وَكُلُّ مَن عَصَى اللهَ فَهُوَ جَاهِلٌ.\nمِن قَرِيبٍقَبلَ مُعَايَنَةِ المَوتِ.\nتَعضُلُوهُنَّلاَ تُمسِكُوهُنَّ مُضَارِّينَ لَهُنَّ.\ndeeds\nاستغفر الله، وتب إليه سبعين مرةً، متذكرًا آخر ذنوبك وأخطائك.\nتأمل من مات على غفلة أو معصية؛ فقد يكون ذلك تذكيرًا لك من ربك، ثم بادر بالتوبة، وإصلاح حياتك.\nادفع وساوس الشيطان لك عن زوجتك أو أختك بالاستعاذة بالله، والنفث عن شمالك.\nguid\nالتوبة أكثر ما يكون نفعها عندما تحصل بعد الذنب مباشرة.\nاحذر الظلم؛ وخاصة ظلم من كان ضعيفًا كالمرأة؛ فإن الله ناصر كل ضعيف، فاحذر عقوبة الله تعالى.\nعلى الرجل أن يعاشر زوجته بالمعروف من: الصحبة الجميلة، وكف الأذى، وبذل الإحسان، وحسن المعاملة، ويدخل في ذلك النفقة والكسوة.\nrefl\nوَٱلَّٰتِي يَأۡتِينَ ٱلۡفَٰحِشَةَ مِن نِّسَآئِكُمۡ فَٱسۡتَشۡهِدُواْ عَلَيۡهِنَّ أَرۡبَعَةٗ مِّنكُمۡۖ\nقيل: إنَّما جعل شهداء الزنا أربعة تغليظًا على المدّعي، وسترًا على العباد. ابن جزي: ١/١٧٩.\nاذكر حكمة مِن حِكَم جعل الشهداء على الزنا أربعة.\nوَٱلَّٰتِي يَأۡتِينَ ٱلۡفَٰحِشَةَ مِن نِّسَآئِكُمۡ\nأي: الزنا، ووصفها بالفاحشة لشناعتها وقبحها. السعدي: ١٧١.\nلماذا وصف الزنا بالفاحشة؟\nإِنَّ ٱللَّهَ كَانَ تَوَّابٗا رَّحِيمًا ١٦\n(رحيمًا) أي: يخص من يشاء من عباده بالتوفيق لما يرضاه له، فتخلَّقوا بفعله سبحانه، وارحموا المذنبين إذا تابوا، ولا يكن أذاكم لهم إلا لله؛ ليرجعوا، وليكن أكثر كلامكم لهم الوعظ بما يقبل بقلوبهم. البقاعي: ٢/٢٢٦.\nما دلالة ختم الآية باسمي الله تعالى (التواب)، و(الرحيم)؟\nإِنَّمَا ٱلتَّوۡبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعۡمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٖ\nأي: جهالة منه بعاقبتها، وإيجابها لسخط الله وعقابه، وجهل منه بنظر الله ومراقبته له، وجهل منه بما تؤول إليه من نقص الإيمان، أو إعدامه؛ فكل عاص لله فهو جاهل بهذا الاعتبار وإن كان عالمًا بالتحريم. السعدي: ١٧١.\nما حقيقة الجهل الذي يحصل من عامل السوء؟\nوَعَاشِرُوهُنَّ بِٱلۡمَعۡرُوفِۚ\nالخطاب للجميع؛ إذ لكل أحد عِشرة؛ زوجًا كان، أو وليًا، ولكن المراد بهذا الأمر في الأغلب الأزواج، وهو مثل قوله تعالى: ﴿فَإِمۡسَاكُۢ بِمَعۡرُوفٍ﴾؛ وذلك توفية حقها من المهر والنفقة، وألا يعبس في وجهها بغير ذنب، وأن يكون منطلقًا في القول؛ لا فظًا، ولا غليظًا، ولا مظهرًا ميلًا إلى غيرها. القرطبي: ٦/١٥٩.\nكيف تكون المعاشرة بالمعروف؟\nفَإِن كَرِهۡتُمُوهُنَّ فَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرٗا كَثِيرٗا ١٩\nأي: ينبغي لكم أيها الأزواج أن تمسكوا زوجاتكم مع الكراهة لهن؛ فإن في ذلك خيرًا كثيرًا؛ من ذلك: امتثال أمر الله، وقبول وصيته التي فيها سعادة الدنيا والآخرة، ومنها: أن إجباره نفسه -مع عدم محبته لها- فيه مجاهدة النفس، والتخلق بالأخلاق الجميلة، وربما أن الكراهة تزول، وتخلفها المحبة، كما هو الواقع في ذلك، وربما رزق منها ولدًا صالحًا، نفع والديه في الدنيا والآخرة. السعدي: ١٧٢.\nما الفوائد المترتبة على إمساك الزوجة التي يكرهها الزوج؟\nفَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرٗا كَثِيرٗا ١٩\nإن كرهتموهن؛ فاصبروا عليهن، ولا تفارقوهن لكراهة الأنفس وحدها، فلعل لكم فيما تكرهونه خيرًا كثيرًا؛ فإن النفس ربما تكره ما يحمد، وتحب ما هو بخلافه، فليكن مطمح النظر ما فيه خير وصلاح، دون ما تهوى الأنفس؟ الألوسي: ٤/٢٤٣\nماذا يترتب على طاعة النفس في كل شيء؟"],[81,"§النساء\nwords\nقِنطَارًامَالًا كَثِيرًا.\nبُهتَانًاكَذِبًا، وَظُلمًا.\nأَفضَىاستَمتَعَ بِالجِمَاعِ.\nوَرَبَائِبُكُمُبَنَاتُ نِسَائِكُمُ اللاَّتِي يَتَرَبَّينَ غَالِبًا فِي بُيُوتِكُم.\nوَحَلاَئِلُزَوجَاتُ.\ndeeds\nاكتب مقدار صداق بنات النبي، وانشره في رسالة.\nاجمع أنواع الضعفة الذين دافع الله عن حقوقهم في سورة النساء، وأرسلها في رسالة؛ لتحبب الخلق إلى خالقهم.\nاجمع ثلاثة أحكام شُرعت للمحافظة على علاقات أولي الأرحام، لتعرف عظم شأن الرحم عند الله سبحانه.\nguid\nالتشديد في تحريم استرجاع المهر يؤدي إلى ردع المتلاعبين بالطلاق.\nوجوب الوفاء بالعهود واحترامها وتقديرها.\nمن مراعاة الشرع للحفاظ على أواصر الرحم أن حرم الجمع بين الأختين؛ خشية أن تقطع الرحم بسبب النكاح.\nrefl\nوَإِنۡ أَرَدتُّمُ ٱسۡتِبۡدَالَ زَوۡجٖ مَّكَانَ زَوۡجٖ وَءَاتَيۡتُمۡ إِحۡدَىٰهُنَّ قِنطَارٗا\nالأفضل واللائق الاقتداء بالنبي -صلى الله عليه وسلم- في تخفيف المهر. السعدي: ١٧٣.\nما الأفضل في مقدار المهر؟\nوَإِنۡ أَرَدتُّمُ ٱسۡتِبۡدَالَ زَوۡجٖ مَّكَانَ زَوۡجٖ وَءَاتَيۡتُمۡ إِحۡدَىٰهُنَّ قِنطَارٗا فَلَا تَأۡخُذُواْ مِنۡهُ شَيۡـًٔاۚ أَتَأۡخُذُونَهُۥ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا ٢٠\nوإنَّما جعل هذا الأخذ بهتانًا؛ لأنهم كان من عادتهم إذا كرهوا المرأة وأرادوا طلاقها رموها بسوء المعاشرة، واختلقوا عليها ما ليس فيها، لكي تخشى سوء السمعة فتبذل للزوج مالًا فداءً ليطلّقها. ابن عاشور:٤/ ٢٨٩.\nلماذا سمي أخذ الصداق الذي دفعه الزوج لزوجته بهتانًا في الآية الكريمة؟\nوَكَيۡفَ تَأۡخُذُونَهُۥ وَقَدۡ أَفۡضَىٰ بَعۡضُكُمۡ إِلَىٰ بَعۡضٖ وَأَخَذۡنَ مِنكُم مِّيثَٰقًا غَلِيظٗا ٢١\nوالميثاق الغليظ الذي أخذه للنساء على الرجال: إمساك بمعروف، أو تسريح بإحسان. الطبري: ٨/١٢٧.\nما الميثاق الغليظ الذي أخذته الزوجة على زوجها؟\nوَكَيۡفَ تَأۡخُذُونَهُۥ وَقَدۡ أَفۡضَىٰ بَعۡضُكُمۡ إِلَىٰ بَعۡضٖ وَأَخَذۡنَ مِنكُم مِّيثَٰقًا غَلِيظٗا ٢١\nلما مضى في الآية المتقدمة حكم الفراق الذي سببه المرأة، وأن للزوج أخذ المال منها عقب ذلك بذكر الفراق الذي سببه الزوج، وبين أنه إذا أراد الطلاق من غير نشوز وسوء عشرة؛ فليس له أن يطلب منها مالًا. القرطبي: ٦/١٧٠.\nمتى يحرم على الزوج أن يطلب مالًا مقابل الطلاق؟\nوَلَا تَنكِحُواْ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدۡ سَلَفَۚ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَمَقۡتٗا وَسَآءَ سَبِيلًا ٢٢\nالفاحشة تتناول العقود الفاحشة، كما تتناول المباشرة بالفاحشة. ابن تيمية: ٢/٢٢٢.\nالفاحشة تتناول العقود والمباشرة، كيف ذلك؟\nحُرِّمَتۡ عَلَيۡكُمۡ أُمَّهَٰتُكُمۡ وَبَنَاتُكُمۡ وَأَخَوَٰتُكُمۡ وَعَمَّٰتُكُمۡ وَخَٰلَٰتُكُمۡ\nفمرجع تحريم هؤلاء المحرمات إلى قاعدة المروءة التابعة لكلية حفظ العرض، من قسم المناسب الضروري، وذلك من أوائل مظاهر الرقي البشري. ابن عاشور: ٤/٢٨٩.\nلماذا حرم نكاح هذه المحرمات من النساء؟\nوَأَن تَجۡمَعُواْ بَيۡنَ ٱلۡأُخۡتَيۡنِ إِلَّا مَا قَدۡ سَلَفَۗ\nذكر الله الجمع بين الأختين، وحَرَّمه... وذلك لما في ذلك من أسباب التقاطع بين الأرحام. السعدي: ١٧٤.\nلماذا حرم الله سبحانه الجمع بين الأختين؟"],[82,"§النساء\nwords\nوَالمُحصَنَاتُالمُتَزَوِّجَاتُ.\nمُحصِنِينَأَعِفَّاءَ عَنِ الحَرَامِ.\nمُسَافِحِينَزَانِينَ.\nطَولًاغِنىً، وَسَعَةً.\nمُتَّخِذَاتِأَخدَانٍ مُصَاحِبَاتِ أَصدِقَاءَ لِلزِّنَا سِرًّا.\nالعَنَتَالوُقُوعَ فِي الزِّنَا.\ndeeds\nبُثّ مفاهيم الحياء، والستر، والحجاب الصحيح للمرأة المسلمة؛ باستخدام الوسائل المتيسرة.\nسل الله تعالى أن يرزقك الصبر، ويوفقك له.\nمهما عظمت ذنوبك استغفر الله تعالى وتب إليه، متذكرًا أن الله تعالى يريد أن يتوب على عباده، ويحب ذلك، فأحسن الظن به.\nguid\nمعاملة الناس تكون بظاهرهم، وليس على المؤمن تتبع البواطن.\nالدين والعقل والإحصان صفات أساس في اختيار الزوجة، وهي مقدمة على غيرها من الصفات.\nفي الصبر خير كثير.\nrefl\nوَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمۡ\nكل ما لم يُذكر في هذه الآية فإنه حلال طيب؛ فالحرام محصور، والحلال ليس له حدّ ولا حصر؛ لطفًا من الله ورحمة، وتيسيرًا للعباد. السعدي: ١٧٤.\nدلت هذه الآية على سهولة هذا الدين، وسعة رحمة الله، وضِّح ذلك.\nوَٱللَّهُ أَعۡلَمُ بِإِيمَٰنِكُمۚ بَعۡضُكُم مِّنۢ بَعۡضٖۚ\nأي: لا تتعرضوا للباطن في الإيمان، وخذوا بالظاهر؛ فإن الله أعلم بإيمانكم. البغوي: ١/٥٠٩.\nهل من منهج المسلم الكلام عن بواطن الناس؟ ولماذا؟\nذَٰلِكَ لِمَنۡ خَشِيَ ٱلۡعَنَتَ مِنكُمۡۚ وَأَن تَصۡبِرُواْ خَيۡرٞ لَّكُمۡۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ٢٥\nقيل: أصل العنت انكسار العظم بعد الجبر؛ فاستعير لكل مشقة وضرر يعتري الإنسان بعد صلاح حاله، ولا ضرر أعظم من مواقعة المآثم بارتكاب أفحش القبائح. الألوسي: ٥/١٢.\nما دلالة الخوف من العنت في الأمر بالزواج بالأمة؟\nفَإِنۡ أَتَيۡنَ بِفَٰحِشَةٖ فَعَلَيۡهِنَّ نِصۡفُ مَا عَلَى ٱلۡمُحۡصَنَٰتِ مِنَ ٱلۡعَذَابِۚ ذَٰلِكَ لِمَنۡ خَشِيَ ٱلۡعَنَتَ مِنكُمۡۚ وَأَن تَصۡبِرُواْ خَيۡرٞ لَّكُمۡۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ٢٥\nوختم هذه الآية بهذين الاسمين الكريمين: (الغفور) و(الرحيم) لكون هذه الأحكام رحمة بالعباد، وكرمًا وإحسانًا إليهم؛ فلم يضيق عليهم، بل وَسَّع عليهم غاية السعة. ولعل في ذكر المغفرة بعد ذكر الحد إشارة إلى أن الحدود كفارات؛ يغفر الله بها ذنوب عباده، كما ورد بذلك الحديث. السعدي: ١٧٥.\nما وجه ختم الآية باسميه: (الغفور)، و(الرحيم)؟\nيُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمۡ وَيَهۡدِيَكُمۡ سُنَنَ ٱلَّذِينَ مِن قَبۡلِكُمۡ\nأي: ﴿لِيُبَيِّنَ لَكُمۡ﴾ أمر دينكم ومصالح أمركم، وما يحل لكم وما يحرم عليكم؛ وذلك يدل على امتناع خلو واقعة عن حكم الله تعالى، ومنه قوله تعالى: ﴿مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٍ﴾ [الأنعام: ٣٨] القرطبي: ٦/٢٤٤.\nهل تحدث واقعة أو نازلة معاصرة ليس لشرع الله تعالى فيها بيان أو حكم؟\nيُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمۡ وَيَهۡدِيَكُمۡ سُنَنَ ٱلَّذِينَ مِن قَبۡلِكُمۡ\nأي: يهديكم مناهج من كان قبلكم من الأنبياء والصالحين لتقتدوا بهم. ابن جزي: ١/١٨٦.\nالمؤمنون على مر السنين إخوة يقتدي بعضهم ببعض، وضح ذلك من الآية.\nيُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمۡ وَيَهۡدِيَكُمۡ سُنَنَ ٱلَّذِينَ مِن قَبۡلِكُمۡ وَيَتُوبَ عَلَيۡكُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ٢٦\n﴿وَيَتُوبَ عَلَيۡكُمۡۗ﴾ أي: يلطف بكم في أحوالكم وما شرعه لكم، حتى تتمكنوا من الوقوف على ما حده الله، والاكتفاء بما أحله، فتقل ذنوبكم بسبب ما يسر الله عليكم؛ فهذا من توبته على عباده. ومن توبته عليهم أنهم إذا أذنبوا فتح لهم أبواب الرحمة، وأوزع قلوبهم الإنابة إليه والتذلل بين يديه، ثم يتوب عليهم بقبول ما وفقهم له.السعدي:١٧٥.\nكيف يتوب الله على عباده؟"],[83,"§النساء\nwords\nكَبَائِرَالذُّنُوبَ الكَبِيرَةَ مِمَّا فِيهِ حَدٌّ، أَو لَعنَةٌ، أَو وَعِيدٌ.\nسَيِّئَاتِكُمالذُّنُوبَ الصَّغِيرَةَ.\nمَوَالِيَوَرَثَةً.\nوَالَّذِينَ عَقَدَت أَيمَانُكُممَن حَالَفتُمُوهُم عَلَى النُّصرَةِ.\ndeeds\nتعبد الله بعمل إعلامي: (رسالة - مقال- عرض مرئي- قصيدة) تحذر فيها من الشهوات التي استطاع المفسدون نشرها في البلد.\nتضرّع إلى الله معترفًا بضعفك وعجزك؛ فإن الله تعالى مع المنكسرة قلوبهم إليه.\nاجتنب مجلسًا أو مكانًا يذكرك بكبيرة من كبائر الذنوب، وأكثر من الاستغفار.\nguid\nالمبتلى بالشهوات المحرمة يرغب في كون الناس كلهم مثله، كما أن الطاهر يود أن كل الناس طاهرون.\nما من إنسان إلا يختبره الله بنوعين من الدعاة: دعاة إلى الخير، ودعاة إلى الشر.\nمالُ الآخرين لا يجوز أكله إلا بطريقة شرعية، وبرضا نفس منه؛ فاحذر أن تدخل في بطنك المال الحرام.\nrefl\nوَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيۡكُمۡ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُواْ مَيۡلًا عَظِيمٗا ٢٧\nفإذا عرفتم أن الله يأمركم بما فيه صلاحكم وفلاحكم وسعادتكم، وأن هؤلاء المتبعين لشهواتهم يأمرونكم بما فيه غاية الخسار والشقاء؛ فاختاروا لأنفسكم أَولى الداعيين، وتخيروا أحسن الطريقتين. السعدي: ١٧٥.\nبَيَّن الله الطرق للناس، فماذا بقي عليهم؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ ... وَلَا تَتَمَنَّوۡاْ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖۚ\nلما نهى الله تعالى عن أكل أموال الناس بالباطل، وقتل الأنفس عقبه بالنهي عما يؤدي إليه من الطمع في أموالهم؛ نهاهم أولًا عن التعرض لأموالهم بالجوارح، ثم عن التعرض لها بالقلب على سبيل الحسد؛ لتطهر أعمالهم الظاهرة والباطنة. الألوسي: ٥/١٩.\nما علة النهي عن تمني نعمة الآخرين؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٖ مِّنكُمۡۚ\nوهذه الآية أدل دليل على فساد قول الجهلة من المتصوفة المنكرين طلب الأقوات بالتجارات والصناعات. القرطبي: ٦/٢٥٠.\nهل السعي في طلب الرزق والتجارة ينافي التوكل على الله، وضح ذلك من الآية.\nإِن تَجۡتَنِبُواْ كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَنُدۡخِلۡكُم مُّدۡخَلٗا كَرِيمٗا ٣١\nقال ابن عباس: \"الكبائر كل ذنب ختمه الله بنار، أو لعنة، أو غضب\". ابن جزي: ١/١٨٧.\nما المراد بالكبائر، مع التمثيل لثلاثة منها؟\nوَلَا تَتَمَنَّوۡاْ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖۚ لِّلرِّجَالِ نَصِيبٞ مِّمَّا ٱكۡتَسَبُواْۖ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا ٱكۡتَسَبۡنَۚ وَسۡـَٔلُواْ ٱللَّهَ مِن فَضۡلِهِۦٓۚ\n(ولا تتمنوا...) الآية: سببها أن النساء قلن: ليتنا استوينا مع الرجال في الميراث، وشاركناهم في الغزو؛ فنزلت نهيًا عن ذلك؛ لأن في تمنيهم ردًّا على حكم الشريعة، فيدخل في النهي تمني مخالفة الأحكام الشرعية كلها. ابن جزي: ١/١٨٧.\nلماذا جاء النهي عن تمني ما فضّل الله به بعض الناس على بعض؟\nوَلَا تَتَمَنَّوۡاْ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖۚ\nفنهى الله تعالى عن التمني لما فيه من دواعي الحسد. والحسد: أن يتمنى زوال النعمة عن صاحبه، سواء تمناها لنفسه أم لا؛ وهو حرام، والغبطة: أن يتمنى لنفسه مثل ما لصاحبه؛ وهو جائز. قال الكلبي: \"لا يتمنى الرجل مال أخيه ولا امرأته ولا خادمه، ولكن ليقل اللهم ارزقني مثله\". البغوي: ١/٥١٧.\nما الفرق بين الحسد والغبطة؟\nلِّلرِّجَالِ نَصِيبٞ مِّمَّا ٱكۡتَسَبُواْۖ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا ٱكۡتَسَبۡنَۚ\nعبر عن فضل الله بالاكتساب تأكيدًا لاستحقاق كل منهما لنصيبه، وتقوية لاختصاصه؛ بحيث لا يتخطاه إلى غيره؛ فإن ذلك مما يوجب الانتهاء عن التمني المذكور، فلكلٍّ حظٌ من الثواب على حسب ما كلّفه الله تعالى من الطاعات بحسن تدبيره. الألوسي: ٥/١٩.\nلماذا عبر عن فضل الله بالاكتساب؟"],[84,"§النساء\nwords\nنُشُوزَهُنَّعِصيَانَهُنَّ وَتَرَفُّعَهُنَّ عَن طَاعَتِكُم.\nوَالجَار الجُنُبِالجَارِ غَيرِ القَرِيبِ.\nوَالصَّاحِبِ بِالجَنبِالرَّفِيقِ فِي السَّفَرِ وَالحَضَرِ.\nمُختَالًامُتَكَبِّرًاْ، مُعجَبًا بِنَفسِهِ.\ndeeds\nاجمع صفات الصالحات من الآية، ثم أرسلها برسالة تفيد بها النساء.\nاسع في صلح بين زوجين مختلفين عملًا بالآية.\nادع الله تعـالى لـوالديك وجيرانـك؛ فهو من أعظـم الإحسـان إليـهم.\nguid\nوَصَّاك الله بجمعٍ من الناس؛ فاحرص على تنفيذ وصية الله فيهم.\nالفخر والخيلاء ليسا من أوصاف المسلمين؛ فابتعد عنهما.\nالبخل من الصفات المذمومة في المرء، وتزداد المذمة إذا كان البخيل آمرًا لغيره بالبخل.\nrefl\nٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعۡضَهُمۡ عَلَىٰ بَعۡضٖ\nفتفضيل الرجال على النساء من وجوه متعددة: من كون الولايات مختصة بالرجال، والنبوة، والرسالة، واختصاصهم بكثير من العبادات؛ كالجهاد، والأعياد، والجُمَع، وبما خصّهم الله به من العقل، والرزانة، والصبر، والجَلَد الذي ليس للنساء مثله، وكذلك خصهم بالنفقات على الزوجات، بل وكثير من النفقات يختص بها الرجال، ويتميزون عن النساء. السعدي: ١٧٧.\nاذكر ثلاثة من الأوجه التي ميّز الله بها الرجال عن النساء؟\nفَٱلصَّٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٞ لِّلۡغَيۡبِ بِمَا حَفِظَ ٱللَّهُۚ\nأي: النساء الصالحات في دينهن مطيعات لأزواجهن، أو مطيعة لله في حق أزواجهن ﴿حَٰفِظَٰتٌ لِّلۡغَيۡبِ﴾ أي: تحفظ كل ما غاب عن علم زوجها؛ فيدخل في ذلك صيانة نفسها وحفظ ماله وبيته، وحفظ أسراره. ﴿بِمَا حَفِظَ ٱللَّهُۚ﴾ أي: بحفظ الله ورعايته، أو بأمره للنساء أن يطعن الزوج ويحفظنه. ابن جزي: ١/١٨٨.\nما صفات النساء الصالحات؟\nحَٰفِظَٰتٞ لِّلۡغَيۡبِ بِمَا حَفِظَ ٱللَّهُۚ\nوذلك بحفظ الله لهن، وتوفيقه لهن، لا من أنفسهن؛ لأن النفس أمَّارة بالسوء، ولكن من توكل على الله كفاه ما أهمّه من أمر دينه ودنياه. السعدي: ١٧٧.\nما وجه تقييد حفظ النساء لأزواجهن بحفظ الله؟\nفَٱلصَّٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٞ لِّلۡغَيۡبِ بِمَا حَفِظَ ٱللَّهُۚ\nيحفظن أنفسهن وفروجهن في حالة غيبة أزواجهن، وكذلك ما يجب حفظه في النفس والمال، وحافظات لأسرار أزواجهن؛ أي: ما يقع بينهم وبينهن في الخلوة. الألوسي: ٥/٢٤.\nما دلالة وصف الصالحات من المؤمنات بأنهن حافظات للغيب؟\nفَإِنۡ أَطَعۡنَكُمۡ فَلَا تَبۡغُواْ عَلَيۡهِنَّ سَبِيلًاۗ إِنَّ ٱللَّهَ كَانَ عَلِيّٗا كَبِيرٗا ٣٤\nتجاوزوا أنتم عن سيئات أزواجكم، واعفوا عنهن إذا تُبن، أو أنه تعالى قادر على الانتقام منكم، غير راضٍ بظلم أحد، أو أنه سبحانه -مع علوه المطلق وكبريائه- لم يكلفكم إلا ما تطيقون؛ فكذلك لا تكلفوهن إلا ما يطقن. الألوسي: ٥/٢٦.\nما دلالة ختم الآية بقوله: ﴿إِنَّ ٱللَّهَ كَانَ عَلِيًّا كَبِيرًا﴾؟\nإِنَّ ٱللَّهَ كَانَ عَلِيّٗا كَبِيرٗا ٣٤\nتهديد للرجال إذا بغوا على النساء من غير سبب؛ فإن الله العلي الكبير، وهو منتقم ممن ظلمهن وبغى عليهن. ابن كثير: ١/٤٦٧.\nما وجه ختم الآية بوصفه العلي الكبير؟\nوَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗا\nقال العلماء: فأحق الناس بعد الخالق المنان بالشكر والإحسان، والتزام البر والطاعة له والإذعان: من قرن الله الإحسان إليه بعبادته وطاعته، وشكره بشكره؛ وهما الوالدان. القرطبي: ٦/٣٠٢.\nمن أحق الناس بالشكر بعد الله تعالى؟"],[85,"§النساء\nwords\nتَكُتَكُن.\nعَابِرِي سَبِيلٍمُجتَازِي المَسجِدِ مِن بَابٍ إِلَى بَابٍ.\nلاَمَستُمُجَامَعتُم.\nفَتَيَمَّمُوااقصِدُوا.\nصَعِيدًامَا كَانَ عَلَى وَجهِ الأَرضِ مِن تُرَابٍ، وَنَحوِهِ.\nطَيِّبًاطَاهِرًا.\ndeeds\nتصدق اليوم بصدقة خفية، ولو كانت قليلة.\nتدبر هذه الآية، وتذكر دموع حبيبك -صلى الله عليه وسلم- لمَّا سمعها.\nتعلم اليوم أحكام التيمم.\nguid\nلا تحقر الحسنة الصغيرة، ولا السيئة الصغيرة.\nسيأتي يومٌ يندم فيه من خالف الرسول وعصاه؛ فاحرص على الاتّباع حتى لا تكون من النادمين.\nحرص شريعتنا على التيسير ورفع الحرج؛ حيث أباح الله تعالى التيمم عند فقد الماء.\nrefl\nوَإِن تَكُ حَسَنَةٗ يُضَٰعِفۡهَا وَيُؤۡتِ مِن لَّدُنۡهُ أَجۡرًا عَظِيمٗا ٤٠\nقال أبو هريرة -رضي الله عنه-: \"وإذا قال الله: ﴿أَجۡرٌ عَظِيمٌ﴾ فمن الذي يقدر قدره\". القرطبي: ٦/٣٢٤.\nعلى أي شيء يدل قول الله تعالى عن ثوابه: (عظيمًا)؟\nوَإِن تَكُ حَسَنَةٗ يُضَٰعِفۡهَا\nإلى عشرة أمثالها، إلى أكثر من ذلك؛ بحسب: حالها، ونفعها، وحال صاحبها؛ إخلاصًا، ومحبة، وكمالًا. السعدي: ١٧٩.\nما الأسباب التي تجعل الحسنات متفاوتة في المضاعفة؟\nفَكَيۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۢ بِشَهِيدٖ وَجِئۡنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدٗا ٤١\nوقال النبي -صلى الله عليه وسلم- لابن مسعود -رضي الله عنه-: «اقرأ عليَّ القرآن» فقال: أقرأ عليك وعليك أنزل! قال: «إني أحب أن أسمعه من غيري»؛ فقرأت عليه سورة النساء حتى إذا بلغت هذه الآية: ﴿فَكَيۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۭ بِشَهِيدٍ وَجِئۡنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدًا﴾، فقال: «حسبك»، فنظرت فإذا عيناه تذرفان بالدمع. ابن تيمية: ٢/٢٤٩.\nلماذا بكى النبي -صلى الله علية وسلم- عند سماع هذه الآية الكريمة؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ\nرمز إلى أنه ينبغي للمصلي أن يتحرز عما يلهيه ويشغل قلبه، وأن يزكي نفسه عما يدنسها؛ لأنه إذا وجب تطهير البدن فتطهير القلب أولى، أو لأنه إذا صين موضع الصلاة عمّن به حدث فلأن يصان القلب عن خاطر غير طاهر ظاهر الأولوية. الألوسي: ٥/٤٠١.\nإلى ماذا يرمز النهي عن قربان الصلاة حال السكر؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ\nويؤخذ من المعنى: منع الدخول في الصلاة في حال النعاس المفرط، الذي لا يشعر صاحبه بما يقول ويفعل، بل لعل فيه إشارة إلى أنه ينبغي لمن أراد الصلاة أن يقطع عنه كل شاغل يشغل فكُره؛ كمدافعة الأخبثين، والتَّوق لطعامٍ ونحوه. السعدي: ١٧٩.\nدَلَّت الآية على وجوب تفريغ الذهن لمن أراد أن يصلي، وضِّح ذلك.\nفَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُمۡۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا ٤٣\nوأحسب أن حكمة تشريعه تقرير لزوم الطهارة في نفوس المؤمنين، وتقرير حرمة الصلاة، وترفيع شأنها في نفوسهم، فلم تترك لهم حالة يعدون فيها أنفسهم مصلين بدون طهارة؛ تعظيمًا لمناجاة الله تعالى. ابن عاشور: ٥/٦٩.\nما حكمة تشريع التيمم؟\nفَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُمۡۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا ٤٣\nوقوله: ﴿إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا﴾ تذييل لحكم الرخصة؛ إذ عفا عن المسلمين فلم يكلفهم الغسل أو الوضوء عند المرض، ولا ترقب وجود الماء عند عدمه، حتى تكثر عليهم الصلوات؛ فيعسر عليهم القضاء. ابن عاشور: ٥/٧١.\nما مناسبة اختتام آية تشريع التيمم بقوله تعالى: ﴿إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا﴾؟"],[86,"§النساء\nwords\nوَاسمَع غَيرَ مُسمَعٍيَدعُونَ عَلَى النَّبِيِّ -صلّى الله عليه وسلّم- قَائِلِينَ: اسمَع مِنَّا لاَ سَمِعتَ!\nوَرَاعِنَاافهَم عَنَّا، وَأَفهِمنَا.\nلَيًّا بِأَلسِنَتِهِميَلوُونَ أَلسِنَتَهُم بِذَلِكَ، وَهُم يُرِيدُونَ الدُّعَاءَ عَلَيهِ بِالرُّعُونَةِ حَسَبَ لُغَتِهِم.\ndeeds\nأرسل رسالة تحذر فيها من يحلف بغير الله تعالى؛ كالحلف بالنبي -صلى الله علية وسلم- أو بالأمانة، ونحوها.\nقـل: \"اللهم آتِ نفسي تقواها، وزكـها أنت خير من زكاها\".\nحدد ظلمًا عانيت منه، واستنصر بربك وحده، وقل: \"يا نصير انصرني\".\nguid\nمن حَرَّفَ معاني القرآن الكريم فقد أشبه اليهود والنصارى.\nعلى من أراد معرفة الحق أن يتأدب مع العلماء والدعاة، وأن يحسن صيغة سؤاله لهم، ويتلطف معهم.\nالذنوب قد يغفرها الله للعبد بالتوبة، أو يكفرها بالأعمال الصالحة، أو يغفرها سبحانه تفضلًا منه ورحمة، أما الشرك فإنه لا يُغفر فاحذر.\nrefl\nوَٱللَّهُ أَعۡلَمُ بِأَعۡدَآئِكُمۡۚ وَكَفَىٰ بِٱللَّهِ وَلِيّٗا وَكَفَىٰ بِٱللَّهِ نَصِيرٗا ٤٥\n﴿وَٱللَّهُ أَعۡلَمُ بِأَعۡدَآئِكُمۡۚ﴾ منكم؛ فلا تستنصحوهم؛ فإنهم أعداؤكم، ﴿وَكَفَىٰ بِٱللَّهِ وَلِيًّا وَكَفَىٰ بِٱللَّهِ نَصِيرًا﴾. البغوي: ١/٥٤٢.\nعن أي شيء نهانا القرآن في هذه الآية؟\nوَٱللَّهُ أَعۡلَمُ بِأَعۡدَآئِكُمۡۚ وَكَفَىٰ بِٱللَّهِ وَلِيّٗا وَكَفَىٰ بِٱللَّهِ نَصِيرٗا ٤٥\nفلا تلتفتوا إليهم، ولا تكونوا في فكر منهم، ﴿وَكَفَىٰ بِٱللَّهِ وَلِيًّا﴾ يلي أمركم وينفعكم بما شاء، ﴿وَكَفَىٰ بِٱللَّهِ نَصِيرًا﴾ يدفع عنكم مكرهم وشرهم؛ فاكتفوا بولايته ونصرته، ولا تبالوا بهم، ولا تكونوا في ضيق مما يمكرون. الألوسي: ٥/٤٥.\nعلى ماذا يدل إخبار الله تعالى بولايته ونصرته للمؤمنين؟\nمِّنَ ٱلَّذِينَ هَادُواْ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعۡنَا وَعَصَيۡنَا\nفهذا حالهم في العلم: أشر حال؛ قلبوا فيه الحقائق، ونزلوا الحق على الباطل، وجحدوا لذلك الحق. وأمَّا حالهم في العمل والانقياد فإنهم: (يقولون سمعنا وعصينا). السعدي: ١٨١.\nاليهود شر الناس علمًا وعملًا، وضح ذلك من الآية.\nيَٰٓأَيُّهَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ ءَامِنُواْ بِمَا نَزَّلۡنَا مُصَدِّقٗا لِّمَا مَعَكُم مِّن قَبۡلِ أَن نَّطۡمِسَ وُجُوهٗا فَنَرُدَّهَا عَلَىٰٓ أَدۡبَارِهَآ\nقال مالك -رحمه الله-: كان أول إسلام كعب الأحبار أنه مر برجل من الليل وهو يقرأ هذه الآية: (يا أيها الذين أوتوا الكتاب آمنوا...) فوضع كفيه على وجهه، ورجع القهقرى إلى بيته، فأسلم مكانه، وقال: \"والله لقد خفت ألا أبلغ بيتي حتى يطمس وجهي\". القرطبي: ٦/٤٠٤.\nكيف أثرت هذه الآية في كعب الأحبار -رحمه الله- لمَّا سمعها؟\nأَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُمۚ بَلِ ٱللَّهُ يُزَكِّي مَن يَشَآءُ وَلَا يُظۡلَمُونَ فَتِيلًا ٤٩ ٱنظُرۡ كَيۡفَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ\nهذا من أعظم الافتراء على الله؛ لأن مضمون تزكيتهم لأنفسهم: الإخبار بأن الله جعل ما هم عليه حقًا، وما عليه المؤمنون المسلمون باطلًا، وهذا أعظم الكذب، وقلب الحقائق بجعل الحق باطلًا، والباطل حقًا. السعدي: ١٨٢.\nكيف كان في تزكيتهم لأنفسهم افتراء الكذب على الله؟\nأَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُمۚ بَلِ ٱللَّهُ يُزَكِّي مَن يَشَآءُ وَلَا يُظۡلَمُونَ فَتِيلًا ٤٩\nهذه الآية وقوله تعالى: ﴿فَلَا تُزَكُّوٓاْ أَنفُسَكُمۡ﴾ [النجم: ٣٢] يقتضي الغض من المزكي لنفسه بلسانه، والإعلام بأن الزاكي المزكَّى من حسنت أفعاله، وزكاه الله -عز وجل-؛ فلا عبرة بتزكية الإنسان نفسه، وإنَّما العبرة بتزكية الله له. القرطبي: ٦/٤٠٧-٤٠٨.\nمَنِ العبد الـمزكَّى حقيقة؟\nأَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُؤۡمِنُونَ بِٱلۡجِبۡتِ وَٱلطَّٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُواْ هَٰٓؤُلَآءِ أَهۡدَىٰ مِنَ ٱلَّذِينَ ءَامَنُواْ سَبِيلًا ٥١\n(الجبت): السحر. و(الطاغوت): الشيطان والوثن. وهذه حال كثير من المنتسبين إلى الملة؛ يعظمون السحر والشرك، ويرجحون الكفار على كثير من المؤمنين المتمسكين بالشريعة. ابن تيمية: ٢/٢٦٦.\nبيّن خطورة الشرك والسحر على الأمة."]])